insert into ponew values
(1, 1, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The process by which water and diffusible substances move together across a membrane in response to fluid pressure is:', '["Diffusion", "Filtration", "Active transport", "Osmosis"]'::jsonb, 1, 'Filtration moves water and small solutes together across a membrane under hydrostatic (fluid) pressure, as at the glomerulus.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 2, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The part of the ear that functions in both hearing and balance is the:', '["Eustachian tube", "Inner ear", "Outer ear", "Middle ear"]'::jsonb, 1, 'The inner ear holds the cochlea (hearing) and the vestibular apparatus (balance).', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 3, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Which muscle aids deep (forced) expiration?', '["Rectus abdominis", "External intercostals", "Scalenes", "Sternocleidomastoid"]'::jsonb, 0, 'Forced (deep) expiration uses the abdominal muscles, such as rectus abdominis, and the internal intercostals. Scalenes, SCM and external intercostals are inspiratory.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 4, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The correct order of the main stages of haemostasis is:', '["Vascular spasm, platelet plug, then coagulation", "Platelet plug, fibrinolysis, then vascular spasm", "Coagulation, then vascular spasm, then platelet plug", "Fibrinolysis, coagulation, then the platelet plug"]'::jsonb, 0, 'Injury causes immediate vasoconstriction, then platelets adhere and aggregate, then the clotting cascade forms fibrin to stabilise the plug. Fibrinolysis later dissolves the clot.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 5, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Water reabsorbed by the collecting duct enters the:', '["Nephron loop", "Minor calyx", "Ureter", "Vasa recta"]'::jsonb, 3, 'Water reabsorbed from the collecting duct passes into the medullary interstitium and is carried away by the vasa recta.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 6, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'What proportion of resting cardiac output goes to the brain?', '["5%", "15%", "10%", "20%"]'::jsonb, 1, 'The brain receives about 15% of resting cardiac output (about 750 mL/min).', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 7, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Aldosterone is secreted from which zone of the adrenal cortex?', '["Zona glomerulosa", "Zona reticularis", "Adrenal medulla", "Zona fasciculata"]'::jsonb, 0, 'The zona glomerulosa, the outermost adrenal cortex layer, produces mineralocorticoids such as aldosterone.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 8, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Which structure connects the pharynx to the bronchi, serving as the main airway?', '["Trachea", "Oesophagus", "Aorta", "Ureter"]'::jsonb, 0, 'The trachea is the main airway connecting the larynx/pharynx above to the bronchi below, allowing air to pass to and from the lungs.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 9, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Residual volume is the amount of air:', '["Remaining in the lungs after maximal expiration", "Exhaled forcefully after normal expiration", "Inhaled during a normal breath", "Inhaled during maximal inspiration beyond tidal volume"]'::jsonb, 0, 'Residual volume is the air that remains in the lungs even after the most forceful expiration, preventing lung collapse.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 10, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Platelets (thrombocytes) primarily function in:', '["Blood clotting/haemostasis", "Oxygen transport", "Producing hormones", "Fighting bacterial infection"]'::jsonb, 0, 'Platelets are essential for haemostasis, aggregating at sites of vessel injury to help form a clot.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 11, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Which organs are both involved in the synthesis of calcitriol and erythropoietin?', '["Thyroid and thymus", "Anterior and posterior pituitary", "Parathyroids and pancreatic islets", "Liver and kidneys"]'::jsonb, 3, 'The liver (25-hydroxylation) and kidney (1-hydroxylation) both make calcitriol. Both also produce erythropoietin, mainly the kidney.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 12, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Which layer of the skin has no blood vessels?', '["Epidermis", "Hypodermis (subcutaneous layer)", "Dermis", "Papillary dermis"]'::jsonb, 0, 'The epidermis is nourished by diffusion from the dermis. This explains why superficial (epidermal) burns do not bleed and heal without scarring.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 13, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'A deficiency of pulmonary surfactant is most likely to cause:', '["Pneumothorax", "Chronic bronchitis", "Atelectasis", "COPD"]'::jsonb, 2, 'Surfactant lowers alveolar surface tension. Without it, alveoli collapse (atelectasis), as in neonatal respiratory distress syndrome.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 14, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Which term is least related to the others?', '["Adipose tissue", "Reticular layer", "Hypodermis", "Subcutaneous fat"]'::jsonb, 1, 'Subcutaneous fat, adipose tissue and the hypodermis all describe the layer beneath the skin. The reticular layer is part of the dermis.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 15, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The nerve at risk during parotid gland surgery, whose injury causes facial weakness on that side, is the:', '["Glossopharyngeal nerve (cranial nerve IX)", "Trigeminal nerve (cranial nerve V)", "Facial nerve (cranial nerve VII)", "Hypoglossal nerve (cranial nerve XII)"]'::jsonb, 2, 'The facial nerve passes through the parotid gland and divides into five branches there. Facial nerve monitoring is often used during parotidectomy.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 16, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The brachial plexus is formed from the anterior rami of spinal nerves:', '["C1 to C4", "C3 to C7", "C5 to T1", "T1 to T6"]'::jsonb, 2, 'The brachial plexus supplies the upper limb. It is at risk from shoulder abduction beyond 90°, the lateral and prone positions, and arm board malposition during surgery.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 17, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Which of the following is NOT a hormone?', '["Thymosin", "Renin", "Atrial natriuretic peptide", "Prolactin"]'::jsonb, 1, 'Renin is an enzyme that converts angiotensinogen to angiotensin I. Prolactin, thymosin and ANP are hormones.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 18, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Which among the following is not usually secreted by the kidneys?', '["Creatine", "Hydrogen", "Bicarbonate", "Creatinine"]'::jsonb, 0, 'The correct answer is: Creatine.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 19, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The normal adult serum potassium range is:', '["5.5–7.0 mmol/L", "3.5–5.0 mmol/L", "135–145 mmol/L", "1.5–2.5 mmol/L"]'::jsonb, 1, 'Potassium is mostly intracellular. Both hypokalaemia and hyperkalaemia cause arrhythmias, and anaesthesia (e.g. suxamethonium) and tissue damage can raise potassium. 135–145 mmol/L is the sodium range.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 20, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The heart''s four chambers consist of:', '["Two atria and two ventricles", "Four ventricles only", "One atrium and three ventricles", "Four atria only"]'::jsonb, 0, 'The heart has two upper chambers (right and left atria) and two lower chambers (right and left ventricles).', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 21, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The epithelial cells lining the endocervical canal are:', '["Tall and squamous", "Tall and columnar", "Flat and transitional", "Tall and cuboidal"]'::jsonb, 1, 'The endocervical canal is lined by tall, mucus-secreting columnar epithelium.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 22, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Cardiac output is calculated as:', '["Stroke volume minus heart rate", "Heart rate divided by stroke volume", "Mean arterial pressure divided by heart rate", "Heart rate multiplied by stroke volume"]'::jsonb, 3, 'Cardiac output (CO) = heart rate (HR) x stroke volume (SV), representing the volume of blood pumped by the heart per minute.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 23, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Which of these is a granulocyte?', '["A macrophage", "A lymphocyte", "An erythrocyte", "An eosinophil"]'::jsonb, 3, 'Granulocytes are neutrophils, eosinophils and basophils. Lymphocytes and monocytes/macrophages are agranulocytes.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 24, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The system that controls the major movements of the body is the:', '["Skeletal system", "Nervous system", "Endocrine system", "Digestive system"]'::jsonb, 1, 'The nervous system directs body movements through motor nerves to skeletal muscles.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 25, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'In an emergency when the recipient''s blood group is unknown, the red cells that can be given are:', '["Group AB Rh-positive", "Group O Rh-negative", "Group B Rh-positive", "Group A Rh-negative"]'::jsonb, 1, 'Group O red cells have no A or B antigens; Rh-negative avoids sensitisation (important in girls and women of childbearing age). Group AB is the universal plasma donor.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 26, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The common bile duct is formed by the union of the:', '["Common hepatic duct and the pancreatic duct", "Pancreatic duct and the cystic duct", "Right and left hepatic ducts", "Cystic duct and the common hepatic duct"]'::jsonb, 3, 'The right and left hepatic ducts join to form the common hepatic duct, which joins the cystic duct to form the common bile duct. It joins the pancreatic duct at the ampulla of Vater.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 27, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Antibodies belong to which class of plasma proteins?', '["Alpha globulins", "Agglutinins", "Albumins", "Gamma globulins"]'::jsonb, 3, 'Antibodies (immunoglobulins) are gamma globulins.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 28, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The normal arterial blood pH range is:', '["7.35–7.45", "7.00–7.20", "7.50–7.65", "6.80–7.00"]'::jsonb, 0, 'Below 7.35 is acidaemia, above 7.45 is alkalaemia. Normal PaCO₂ is 35–45 mmHg and bicarbonate 22–26 mmol/L.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 29, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Most neurones in the CNS are:', '["Pseudounipolar neurones", "Unipolar neurones", "Bipolar neurones", "Multipolar neurones"]'::jsonb, 3, 'Most CNS neurons, including motor neurons and interneurons, are multipolar: one axon and many dendrites.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 30, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The nervous system can inhibit or stimulate other systems in order to maintain:', '["Growth", "Mental balance", "Homeostasis", "Integration"]'::jsonb, 2, 'By stimulating or inhibiting other systems, the nervous system helps maintain homeostasis.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 31, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The levator ani muscle consists of how many muscles?', '["3", "2", "4", "5"]'::jsonb, 0, 'The levator ani has three parts: pubococcygeus, puborectalis and iliococcygeus.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 32, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'Gaseous exchange in the lungs occurs primarily at the level of the:', '["Larynx", "Trachea", "Bronchi", "Alveoli"]'::jsonb, 3, 'The alveoli, with their thin walls and rich capillary network, are the site of gas exchange between air and blood.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 33, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The seminal vesicle measures about ______ in length.', '["4 cm", "3 cm", "5 cm", "10 cm"]'::jsonb, 2, 'Each seminal vesicle is a coiled sac about 5 cm long, lying behind the bladder. It contributes about 60–70% of semen volume.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 34, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'The short period that occurs during the transmission of impulses through the synapses is:', '["Synaptic simulation", "Synaptic delay", "Synaptic cleft", "Synaptic junction"]'::jsonb, 1, 'Synaptic delay (about 0.5 ms) is the time taken for neurotransmitter release, diffusion and receptor binding at a synapse.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 35, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 411 · Applied Anatomy & Physiology', 'McBurney''s point, the usual site of maximum tenderness in appendicitis, lies:', '["One-third of the way from the right anterior superior iliac spine to the umbilicus", "Midway between the umbilicus and the pubic symphysis", "Two-thirds of the way from the umbilicus to the left anterior superior iliac spine", "At the tip of the ninth costal cartilage"]'::jsonb, 0, 'McBurney''s point is on the line from the right ASIS to the umbilicus, one-third of the way from the ASIS. The gridiron (McBurney) incision for open appendicectomy is made here.', 'NNP 411 · Applied Anatomy & Physiology'),
(1, 36, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Microcytic anaemia (low MCV) is classically associated with:', '["Acute haemorrhage only", "Vitamin B12 deficiency", "Folate deficiency", "Iron deficiency"]'::jsonb, 3, 'Iron deficiency anaemia is the classic cause of microcytic (small red cell) anaemia, whereas B12/folate deficiency typically causes macrocytic anaemia.', 'NNP 412 · Applied Biochemistry'),
(1, 37, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Coagulopathy or low platelet count in a patient with GI bleeding:', '["Has no bearing on bleeding risk", "Reduces the risk of rebleeding", "Increases the risk of rebleeding", "Only matters in upper GI bleeds, not lower"]'::jsonb, 2, 'If the blood can''t clot effectively, any bleeding point is far more likely to continue or restart.', 'NNP 412 · Applied Biochemistry'),
(1, 38, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A patient with chronic kidney disease commonly develops which acid-base abnormality due to reduced renal excretion of hydrogen ions and reduced bicarbonate regeneration?', '["Respiratory alkalosis", "Metabolic alkalosis", "Respiratory acidosis", "Metabolic acidosis"]'::jsonb, 3, 'Failing kidneys cannot adequately excrete the daily hydrogen ion load or regenerate bicarbonate, leading to a chronic anion-gap metabolic acidosis characteristic of advanced CKD.', 'NNP 412 · Applied Biochemistry'),
(1, 39, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Kussmaul respiration — deep, rapid breathing — is a compensatory pattern most associated with:', '["Metabolic acidosis", "Normal resting breathing", "Metabolic alkalosis exclusively", "Respiratory acidosis"]'::jsonb, 0, 'Kussmaul respirations are the body''s compensatory response to metabolic acidosis (classically DKA), blowing off CO2 to help correct the pH.', 'NNP 412 · Applied Biochemistry'),
(1, 40, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A patient has fever, chills, and hypotension during transfusion. The nurse suspects:', '["Acute hemolytic reaction", "TRALI", "TACO", "Febrile non-hemolytic reaction"]'::jsonb, 1, 'TRALI presents with acute respiratory distress, fever, and hypotension.', 'NNP 412 · Applied Biochemistry'),
(1, 41, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Which pH finding would be consistent with respiratory alkalosis?', '["7.35", "7.29", "7.49", "7.45"]'::jsonb, 2, 'Respiratory alkalosis comes from hyperventilation (low PaCO2), so the pH is above 7.45.', 'NNP 412 · Applied Biochemistry'),
(1, 42, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A patient''s anion gap has risen by 12 but HCO₃⁻ has fallen by only 6 (delta ratio about 2). This suggests:', '["A coexisting normal-gap acidosis", "Pure respiratory acidosis", "A laboratory error in sodium", "A coexisting metabolic alkalosis"]'::jsonb, 3, 'A delta ratio above 2 means the HCO₃⁻ is higher than expected, so there is also a metabolic alkalosis (e.g. from vomiting or NG suction).', 'NNP 412 · Applied Biochemistry'),
(1, 43, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A patient with an NG tube to suction has metabolic alkalosis. The nurse anticipates:', '["Hypercalcemia", "Hypermagnesemia", "Hypokalemia", "Hypernatremia"]'::jsonb, 2, 'Gastric suctioning causes loss of H⁺, K⁺, and Cl⁻, leading to hypokalemic metabolic alkalosis.', 'NNP 412 · Applied Biochemistry'),
(1, 44, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'The mode of Mechanical Ventilation which has the risk of producing Hyper ventilation and Respiratory Alkalosis is:', '["Synchronous Intermittent Mandatory Ventilation", "Pressure Control Mode", "Controlled Mandatory Ventilation", "Assist Control Mode"]'::jsonb, 3, 'In Assist-Control, every patient trigger gets a full set breath, so a fast-breathing patient can easily hyperventilate.', 'NNP 412 · Applied Biochemistry'),
(1, 45, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Which of the following is true of disseminated intravascular coagulation (DIC)?', '["It is never associated with an underlying condition", "It can cause both blood clots and bleeding", "It is contagious", "It is an inherited disease"]'::jsonb, 1, 'DIC causes widespread microthrombi and, by consuming platelets and clotting factors, bleeding. It is always secondary to an underlying condition.', 'NNP 412 · Applied Biochemistry'),
(1, 46, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'One unit of blood raises the haemoglobin concentration by about:', '["2.2 g/dL", "0.1 g/dL", "1 g/dL", "2 g/dL"]'::jsonb, 2, 'One unit of whole blood or packed red cells raises Hb by about 1 g/dL in an average adult.', 'NNP 412 · Applied Biochemistry'),
(1, 47, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Respiratory failure is defined as:', '["PaO2 >60 mmHg or PaCO2 <50 mmHg", "PaO2 <60 mmHg and/or PaCO2 >50 mmHg", "PaO2 exactly 60 mmHg or PaCO2 exactly 50 mmHg", "PaO2 >60 mmHg and PaCO2 >60 mmHg"]'::jsonb, 1, 'Respiratory failure is PaO2 <60 mmHg (8 kPa) on room air, with or without PaCO2 >50 mmHg (6.5 kPa).', 'NNP 412 · Applied Biochemistry'),
(1, 48, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A nurse is interpreting ABG results for a patient with respiratory failure. The nurse knows that a normal pH range is:', '["7.25 - 7.35", "7.45 - 7.55", "7.35 - 7.45", "7.15 - 7.25"]'::jsonb, 2, 'The normal pH range for arterial blood is 7.35 - 7.45. A pH below this range indicates acidosis, and a pH above this range indicates alkalosis.', 'NNP 412 · Applied Biochemistry'),
(1, 49, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'For suspected acute hemolytic reaction, the nurse’s FIRST action is:', '["Stop the transfusion", "Send blood samples to lab", "Notify the provider", "Administer epinephrine"]'::jsonb, 0, 'Stop transfusion immediately to prevent further hemolysis.', 'NNP 412 · Applied Biochemistry'),
(1, 50, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Which client is most at risk of developing DIC?', '["A 60-year-old client on haemodialysis three times a week", "A 35-year-old pregnant client with placenta praevia", "A 78-year-old client with septicaemia", "A 42-year-old client with a pulmonary embolus"]'::jsonb, 2, 'Sepsis, especially Gram-negative septicaemia, is the commonest cause of DIC.', 'NNP 412 · Applied Biochemistry'),
(1, 51, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A rise in PaCO2 causing acidosis indicates the disorder is:', '["Always compensated", "Metabolic", "Neither respiratory nor metabolic", "Respiratory"]'::jsonb, 3, 'CO2 is controlled by the lungs, so a CO2-driven pH problem is classified as respiratory in origin.', 'NNP 412 · Applied Biochemistry'),
(1, 52, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Which of the following pathogens is a common cause of ventilator-associated pneumonia (VAP) in the ICU?', '["Pseudomonas aeruginosa", "Common cold rhinovirus only", "Malaria parasite", "Tapeworm"]'::jsonb, 0, 'Pseudomonas aeruginosa is a common and often resistant pathogen implicated in ventilator-associated pneumonia in ICU patients.', 'NNP 412 · Applied Biochemistry'),
(1, 53, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A patient is experiencing respiratory failure. Arterial Blood Gas (ABG) results show a PaO₂ of 55 mmHg. Which type of respiratory failure is this most likely to be?', '["There is not enough information to determine the type", "Mixed Respiratory Failure", "Type I (Hypoxemic) Respiratory Failure", "Type II (Hypercapnic) Respiratory Failure"]'::jsonb, 2, 'Type I respiratory failure is defined by a low PaO₂ (typically below 60 mmHg) with a normal or low PaCO₂. The provided value of 55 mmHg falls within the range for Type I respiratory failure.', 'NNP 412 · Applied Biochemistry'),
(1, 54, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Mediastinal change seen in massive pleural effusion on a chest radiograph', '["Shift of mediastinum to the site of effusion", "Tracheal shift to the site of lesion", "Central mediastinum", "Shift of the mediastinum to the opposite"]'::jsonb, 3, 'A massive pleural effusion pushes the mediastinum toward the opposite (unaffected) side.', 'NNP 412 · Applied Biochemistry'),
(1, 55, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'The immediate haemostatic response to a damaged vessel is:', '["Vasoconstriction", "Platelet aggregation", "Platelet adhesion", "Viscous metamorphosis of platelets"]'::jsonb, 0, 'The first response to vessel injury is reflex vasoconstriction, followed by platelet adhesion, aggregation and coagulation.', 'NNP 412 · Applied Biochemistry'),
(1, 56, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'The ''lethal triad'' in polytrauma refers to:', '["Hypoxia, hypercapnia and hypotension", "Tachycardia, tachypnoea and fever", "Hypothermia, acidosis and coagulopathy", "Anaemia, hypokalaemia and hyponatraemia"]'::jsonb, 2, 'Each worsens the others. Warming, early blood products and haemorrhage control break the cycle.', 'NNP 412 · Applied Biochemistry'),
(1, 57, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Autologous transfusion is used for:', '["Neonates", "All patients", "Elective surgery", "Emergency trauma"]'::jsonb, 2, 'Autologous donation is planned for elective procedures.', 'NNP 412 · Applied Biochemistry'),
(1, 58, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A mother is admitted to the emergency department following complaints of fever and chills. The nurse on duty took her vital signs and noted the following: Temp = 100 °F; apical pulse = 95; respiration = 20 and deep. Measurement of arterial blood gas shows pH 7.37, PaO2 90 mm Hg, PaCO2 40 mm Hg, and HCO3 24 mmol/L. What is your assessment?', '["Hyperthermia", "Hyperthermia and Respiratory Alkalosis", "Hypothermia and Respiratory Alkalosis", "Hypothermia"]'::jsonb, 0, 'The ABG is normal (pH 7.37, PaCO2 40, HCO3⁻ 24). The only abnormality is a raised temperature (100 °F): hyperthermia.', 'NNP 412 · Applied Biochemistry'),
(1, 59, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Which collaborative treatment would the nurse anticipate in DIC?', '["Calculating intake and output only", "Oral anticoagulants", "Fresh frozen plasma", "Plasmapheresis"]'::jsonb, 2, 'DIC is treated by treating the cause and replacing what has been consumed: FFP, platelets and cryoprecipitate.', 'NNP 412 · Applied Biochemistry'),
(1, 60, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A patient in DKA presents with deep, rapid breathing (Kussmaul respirations) and a fruity breath odour. This reflects the body''s attempt to:', '["Increase oxygen delivery with no relation to acid-base status", "Compensate for metabolic acidosis by blowing off CO2", "Compensate for respiratory alkalosis", "Reduce blood glucose directly through breathing"]'::jsonb, 1, 'Kussmaul respirations are a compensatory response to the metabolic acidosis of DKA, with deep rapid breathing reducing CO2 to help raise pH; the fruity odour comes from exhaled ketones.', 'NNP 412 · Applied Biochemistry'),
(1, 61, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'A patient is diagnosed with metabolic acidosis, which would the nurse expect the health care provider to order?', '["Potassium", "Serum sodium level", "Bronchodilator", "Sodium bicarbonate"]'::jsonb, 3, 'Severe metabolic acidosis may be treated with sodium bicarbonate, along with treating the cause.', 'NNP 412 · Applied Biochemistry'),
(1, 62, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Percussion as an airway clearance technique is contraindicated in a patient with:', '["Retained secretions", "Post-operative atelectasis", "Platelet count <20,000", "Cystic fibrosis"]'::jsonb, 2, 'Very low platelets increase the risk of bruising or bleeding from the repeated impact of percussion.', 'NNP 412 · Applied Biochemistry'),
(1, 63, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'In a patient with sickle cell disease, the anaesthetic team must avoid:', '["Giving IV fluids and oxygen, because they trigger sickling crises", "Oxygen supplementation", "Hypoxia, dehydration, hypothermia and acidosis", "Warming blankets"]'::jsonb, 2, 'These trigger sickling and crises.', 'NNP 412 · Applied Biochemistry'),
(1, 64, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'After a chest injury, ABGs show pH 7.26, PaCO2 52 mmHg, HCO3 25 mmol/L. This is:', '["Respiratory alkalosis", "Respiratory acidosis", "Metabolic alkalosis", "Metabolic acidosis"]'::jsonb, 1, 'Low pH (acidosis), high PaCO2 (respiratory cause) and normal HCO3 (not yet compensated): acute respiratory acidosis.', 'NNP 412 · Applied Biochemistry'),
(1, 65, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 412 · Applied Biochemistry', 'Each unit of blood should be completed within:', '["12 hours of leaving the fridge", "4 hours of leaving the fridge", "30 minutes of leaving the fridge", "24 hours of leaving the fridge"]'::jsonb, 1, 'Longer times increase bacterial growth.', 'NNP 412 · Applied Biochemistry'),
(1, 66, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A drug with a narrow therapeutic index is one where:', '["The effective dose is far below the toxic dose", "The drug can only be given by the oral route", "The drug can never cause toxicity in practice", "The toxic dose is close to the effective dose"]'::jsonb, 3, 'Examples are digoxin, gentamicin, lithium, phenytoin and warfarin. Blood levels or effects must be monitored closely.', 'NNP 413 · Applied Pharmacology'),
(1, 67, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'The concentration of epinephrine used for endoscopic injection in bleeding ulcers is:', '["1:100,000", "1:1,000,000", "1:1,000", "1:10,000"]'::jsonb, 3, 'This diluted concentration is strong enough to cause local vasoconstriction and stop bleeding without excessive systemic effect.', 'NNP 413 · Applied Pharmacology'),
(1, 68, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Flumazenil is used to reverse:', '["Neuromuscular blockade", "Benzodiazepine sedation", "Heparin anticoagulation", "Opioid overdose"]'::jsonb, 1, 'Flumazenil is a benzodiazepine antagonist. It may precipitate seizures in patients on long-term benzodiazepines or with tricyclic overdose.', 'NNP 413 · Applied Pharmacology'),
(1, 69, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient on furosemide (a loop diuretic) should be monitored closely for which electrolyte disturbance?', '["Hypercalcaemia only", "Hypernatraemia only", "Hypokalaemia", "Hyperkalaemia"]'::jsonb, 2, 'Loop diuretics like furosemide promote potassium loss and commonly cause hypokalaemia, requiring regular electrolyte monitoring.', 'NNP 413 · Applied Pharmacology'),
(1, 70, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Low molecular weight heparin (e.g. enoxaparin) is given postoperatively mainly to:', '["Reduce post-operative wound pain", "Prevent DVT and pulmonary embolism", "Prevent stress ulcers in the stomach", "Treat or prevent wound infection"]'::jsonb, 1, 'LMWH is given subcutaneously. Timing around spinal or epidural catheters is critical to prevent spinal haematoma.', 'NNP 413 · Applied Pharmacology'),
(1, 71, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A nurse is monitoring a sedated patient in the ICU using the Richmond Agitation-Sedation Scale (RASS). A score of 0 on the RASS indicates:', '["Alert and calm", "Light sedation", "Unarousable", "Agitated or restless"]'::jsonb, 0, 'The RASS score ranges from -5 (unarousable) to +4 (combative). A score of 0 signifies a patient who is alert, calm, and able to interact appropriately. The other options correspond to different scores on the scale.', 'NNP 413 · Applied Pharmacology'),
(1, 72, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'The following drug is Second-line treatment for cardiogenic shock', '["Amiodarone", "Deltacortil", "Vasopression", "Epinephrine"]'::jsonb, 3, 'After first-line dobutamine/dopamine, epinephrine is commonly used as a second-line agent in cardiogenic shock.', 'NNP 413 · Applied Pharmacology'),
(1, 73, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'NPH insulin is given at 07:30. When will it reach its peak effect?', '["15:30–21:30", "11:30–13:30", "13:30–19:30", "17:30–23:30"]'::jsonb, 2, 'NPH (intermediate) insulin peaks about 6–12 hours after injection, so a 07:30 dose peaks around 13:30–19:30.', 'NNP 413 · Applied Pharmacology'),
(1, 74, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient with Torsades de Pointes is prescribed magnesium sulfate. Which ECG change confirms efficacy?', '["Resolution of U waves", "Narrowed QRS complex", "Absent P waves", "Shortened QT interval"]'::jsonb, 3, 'Magnesium shortens the QT interval, treating Torsades. U waves are associated with hypokalemia.', 'NNP 413 · Applied Pharmacology'),
(1, 75, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'What is the first-line antidote for suspected opioid overdose causing respiratory depression?', '["Atropine", "Naloxone", "N-acetylcysteine", "Flumazenil"]'::jsonb, 1, 'Naloxone is a competitive opioid receptor antagonist that rapidly reverses opioid-induced respiratory and CNS depression.', 'NNP 413 · Applied Pharmacology'),
(1, 76, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Compared with the other agents listed, which is most likely to cause direct, dose-dependent myocardial contractile depression rather than predominantly vasodilation?', '["Halothane", "Isoflurane", "Sevoflurane at low concentrations", "Desflurane"]'::jsonb, 0, 'Halothane depresses myocardial contractility more directly than isoflurane, desflurane, or sevoflurane, which cause relatively more vasodilation with better-preserved cardiac output at equivalent MAC.', 'NNP 413 · Applied Pharmacology'),
(1, 77, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Which antibiotic acts as a protein synthesis inhibitor?', '["Cefotaxime", "Penicillin", "Tetracycline", "Trimethoprim"]'::jsonb, 2, 'Tetracyclines bind the 30S ribosomal subunit and block protein synthesis. Penicillins and cephalosporins act on the cell wall; trimethoprim blocks folate.', 'NNP 413 · Applied Pharmacology'),
(1, 78, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient taking ibuprofen 400 mg twice daily for chronic back pain develops leg oedema. This is most likely caused by:', '["A decrease in renal function", "An increase in plasma proteins", "A low creatinine level", "An increased glomerular filtration rate"]'::jsonb, 0, 'NSAIDs block renal prostaglandins, reducing renal blood flow and GFR and causing sodium and water retention and oedema.', 'NNP 413 · Applied Pharmacology'),
(1, 79, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'The nurse is caring for a patient on a continuous sedative infusion. The nurse should be aware that which of the following is a major complication of prolonged sedation?', '["A decreased need for mechanical ventilation", "Delirium and an increased length of stay in the ICU", "Increased mobility and decreased risk of pressure ulcers", "An increased level of consciousness"]'::jsonb, 1, 'Prolonged sedation can lead to a number of negative consequences, including delirium, an increased length of stay, and an increased risk of long-term cognitive impairment. The goal is to use the least amount of sedation necessary to keep the patient comfortable and safe.', 'NNP 413 · Applied Pharmacology'),
(1, 80, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'This is known as the fright and flight hormone', '["Oxytocin", "Epinephrine", "Vasopressin", "Insulin"]'::jsonb, 1, 'Epinephrine (adrenaline) is known as the fight-or-flight hormone.', 'NNP 413 · Applied Pharmacology'),
(1, 81, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient on warfarin has an INR of 8.0. Which reversal agent is used for active bleeding?', '["Protamine sulfate", "Andexanet alfa", "FFP", "Vitamin K IV"]'::jsonb, 2, 'FFP provides immediate clotting factors for warfarin reversal. Vitamin K works slowly.', 'NNP 413 · Applied Pharmacology'),
(1, 82, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'What is the antidote for a cholinergic crisis caused by anticholinesterase medication overdose?', '["Protamine sulfate", "Naloxone", "Flumazenil", "Atropine"]'::jsonb, 3, 'Atropine, an anticholinergic agent, is used to counteract the excessive muscarinic effects of a cholinergic crisis caused by anticholinesterase overdose.', 'NNP 413 · Applied Pharmacology'),
(1, 83, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Warfarin effect is urgently reversed before emergency surgery with:', '["Vitamin K plus prothrombin complex (or FFP)", "Desmopressin alone, given before the incision", "Protamine sulphate given slowly by IV injection", "Naloxone given in small repeated IV doses"]'::jsonb, 0, 'Vitamin K restores production of factors II, VII, IX and X but takes hours. PCC (or FFP if unavailable) replaces the factors immediately. INR guides treatment.', 'NNP 413 · Applied Pharmacology'),
(1, 84, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Hypnotic medications differ from anxiolytics primarily in their main clinical purpose, which is to:', '["Lower blood pressure", "Reduce anxiety during waking hours specifically", "Induce and maintain sleep", "Treat bacterial infections"]'::jsonb, 2, 'While some drug classes overlap, hypnotics are specifically used to induce/maintain sleep, distinct from anxiolytics'' primary anti-anxiety purpose.', 'NNP 413 · Applied Pharmacology'),
(1, 85, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Furosemide, a loop diuretic, most commonly causes:', '["Weight gain and fluid retention", "Hypercalcaemia and stones", "Hyperkalaemia and oedema", "Hypokalaemia and dehydration"]'::jsonb, 3, 'Electrolytes, fluid balance and blood pressure are monitored. High IV doses given fast can cause ototoxicity.', 'NNP 413 · Applied Pharmacology'),
(1, 86, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Gentamicin requires monitoring because it is:', '["Hepatotoxic only", "Cardiotoxic only", "Nephrotoxic and ototoxic", "A cause of hyperglycaemia"]'::jsonb, 2, 'Aminoglycoside levels are monitored, renal function checked and the drug used cautiously with other nephrotoxins and in the elderly.', 'NNP 413 · Applied Pharmacology'),
(1, 87, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Morphine''s most dangerous side effect after surgery is:', '["Severe diarrhoea", "Malignant hyperthermia", "Rebound hypertension", "Respiratory depression"]'::jsonb, 3, 'Sedation level and respiratory rate are monitored. Increasing sedation is an early warning that precedes respiratory depression. Other effects include nausea, itching, constipation and urinary retention.', 'NNP 413 · Applied Pharmacology'),
(1, 88, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'The specific antidote for benzodiazepine overdose is:', '["Flumazenil", "Naloxone", "Protamine sulfate", "Dantrolene"]'::jsonb, 0, 'Flumazenil is a competitive benzodiazepine receptor antagonist used to reverse benzodiazepine sedation/overdose.', 'NNP 413 · Applied Pharmacology'),
(1, 89, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Which class of immunosuppressant medications, including tacrolimus and cyclosporine, inhibits calcineurin to reduce T-cell activation but carries a significant risk of nephrotoxicity?', '["Induction antibody agents", "Corticosteroids", "Antimetabolites, such as mycophenolate", "Calcineurin inhibitors"]'::jsonb, 3, 'Calcineurin inhibitors such as tacrolimus and cyclosporine block T-cell activation by inhibiting calcineurin-dependent IL-2 production, but are also directly nephrotoxic and require careful therapeutic drug monitoring to balance rejection prevention with drug-induced kidney injury.', 'NNP 413 · Applied Pharmacology'),
(1, 90, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'To ensure homogenization when diluting powdered medication in a vial, the nurse should:', '["Do nothing after adding the solution to the vial.", "Roll the vial gently between the palms.", "Shake the vial vigorously.", "Invert the vial and let it stand for 1 minute."]'::jsonb, 1, 'Roll the vial gently to mix the powder. Shaking causes foaming and can damage some drugs.', 'NNP 413 · Applied Pharmacology'),
(1, 91, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'When preparing patient-controlled analgesia (PCA) for a postoperative patient, the nurse should:', '["Ask another nurse to double-check the setup before use", "Tell the patient to limit button presses", "Tell the patient to dose only when in severe pain", "Give dosing instructions to a cognitively impaired patient"]'::jsonb, 0, 'PCA pumps are high-alert. An independent double-check of the drug, concentration and settings prevents fatal programming errors.', 'NNP 413 · Applied Pharmacology'),
(1, 92, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Vitamin K is used to reverse excessive anticoagulation from which drug?', '["Aspirin", "Warfarin", "Heparin", "Enoxaparin"]'::jsonb, 1, 'Vitamin K restores synthesis of clotting factors suppressed by warfarin, reversing its anticoagulant effect (though onset is slower than with prothrombin complex concentrate).', 'NNP 413 · Applied Pharmacology'),
(1, 93, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Noradrenaline has leaked from a peripheral IV into the tissues. The specific treatment is:', '["Local infiltration with phentolamine", "Local injection of more noradrenaline", "Applying heat and massaging the area", "Giving IV furosemide"]'::jsonb, 0, 'Stop the infusion, leave the cannula to aspirate, elevate the limb and give through a central line.', 'NNP 413 · Applied Pharmacology'),
(1, 94, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Zopiclone, a cyclopyrrolone-class Z-drug similar to zolpidem, is particularly associated with which distinctive adverse effect?', '["A metallic or bitter taste after use", "Malignant hyperthermia", "Severe hepatotoxicity in most patients", "Serotonin syndrome"]'::jsonb, 0, 'Zopiclone is well known for causing a distinctive metallic or bitter aftertaste, in addition to typical Z-drug effects such as next-day sedation.', 'NNP 413 · Applied Pharmacology'),
(1, 95, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A urine test in an undiagnosed diabetic may show........', '["B glucose and high amounts of bilirubin in the urine", "A Glucose and ketones in the urine", "D ketones and adrenaline in the urine", "C Ketones and oxalate in the urine"]'::jsonb, 1, 'Glucose and ketones in urine are classic undiagnosed diabetes findings.', 'NNP 413 · Applied Pharmacology'),
(1, 96, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'One of the following is a muscle relaxant', '["Fortwin", "Pethidine", "Pentazocine", "Midazolam"]'::jsonb, 3, 'Midazolam (via its muscle-relaxant sedative properties) is grouped here as the muscle relaxant, unlike the opioids pentazocine, fortwin, and pethidine.', 'NNP 413 · Applied Pharmacology'),
(1, 97, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'Streptomycin is produced by which organism?', '["Streptomyces noursei", "Streptomyces fradiae", "Streptomyces nodosus", "Streptomyces griseus"]'::jsonb, 3, 'Streptomycin was isolated from Streptomyces griseus (Waksman, 1943).', 'NNP 413 · Applied Pharmacology'),
(1, 98, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'The concentration of inhalational anaesthetic at which a patient responds purposefully to verbal command during emergence is referred to as:', '["Blood-gas MAC", "MAC-awake", "MAC95", "MAC-BAR"]'::jsonb, 1, 'MAC-awake, typically about 0.3-0.5 of standard MAC, is the concentration at which patients begin to respond to verbal commands as anaesthesia lightens.', 'NNP 413 · Applied Pharmacology'),
(1, 99, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A nurse is managing the pain of a patient who is sedated. The nurse knows that the most effective way to assess a sedated patient''s pain is by:', '["Assessing the patient''s heart rate and blood pressure", "Assuming the patient is not in pain since they are sedated", "Using a behavioral pain scale, such as the BPS or CPOT", "Asking the patient to rate their pain on a scale of 1-10"]'::jsonb, 2, 'A sedated patient cannot verbally communicate their pain. The nurse must use a validated behavioral pain scale, such as the Behavioral Pain Scale (BPS) or the Critical-Care Pain Observation Tool (CPOT), which assesses non-verbal signs of pain like facial expressions and body movements.', 'NNP 413 · Applied Pharmacology'),
(1, 100, 'Nephrology Nursing Mock — Day 5 Morning (Nov 2026)', 'NNP 413 · Applied Pharmacology', 'A patient on long-term oral steroids having major surgery needs:', '["A double dose of insulin on the morning", "No special care, as steroids are harmless", "Steroid cover to prevent adrenal crisis", "Steroids stopped one day before surgery"]'::jsonb, 2, 'Long-term steroids suppress the adrenal glands, which cannot respond to surgical stress. Hydrocortisone is given at induction and continued postoperatively.', 'NNP 413 · Applied Pharmacology'),
(2, 1, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Dialyser reuse requires:', '["Storage in tap water", "No testing at all", "Sharing between patients", "Proper cleaning, testing, labelling and patient-specific use"]'::jsonb, 3, 'It is not allowed for hepatitis B–positive patients.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 2, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'A typical dialysate flow rate in standard haemodialysis is:', '["500 mL/min", "10 mL/min", "5 L/min", "50 mL/min"]'::jsonb, 0, 'It is often 1.5–2 times the blood flow.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 3, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Activated carbon tanks in dialysis water treatment remove:', '["Calcium and magnesium", "Chlorine and chloramine", "Aluminium only", "Bacteria only"]'::jsonb, 1, 'Chloramine causes haemolysis if it reaches the patient.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 4, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Tight (minimal) heparin or heparin-free dialysis is used for patients:', '["At high risk of bleeding, e.g. after surgery", "With normal clotting and no risks", "With clotted circuits every session", "Who are hypertensive only"]'::jsonb, 0, 'Saline flushes help reduce circuit clotting.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 5, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Before discharge from the unit, post-dialysis assessment includes:', '["Only the next appointment", "Weight, BP (sitting and standing), access haemostasis and symptoms", "Nothing if the session was normal", "Only the time"]'::jsonb, 1, 'Postural hypotension can cause falls.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 6, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'A femoral dialysis catheter should usually stay in place no longer than about:', '["1 year", "1 day", "5–7 days in bed-bound patients", "6 months"]'::jsonb, 2, 'Femoral lines carry high infection risk.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 7, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'The post-dialysis urea sample should be taken:', '["After slowing the blood pump to avoid recirculation, per protocol", "From the dialysate line", "Before the session starts", "One hour after the patient goes home"]'::jsonb, 0, 'Incorrect sampling falsely raises URR.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 8, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Rope-ladder cannulation of a fistula means:', '["Rotating needle sites along the whole length of the vessel", "Using the same exact holes every time", "Cannulating only the anastomosis", "Using a central catheter"]'::jsonb, 0, 'It reduces aneurysm formation.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 9, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Erythropoietin therapy targets haemoglobin of about:', '["15–17 g/dL", "5–6 g/dL", "20 g/dL", "10–11.5 g/dL"]'::jsonb, 3, 'Higher targets increase stroke and thrombosis.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 10, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Intradialytic hypotension is more likely when:', '["The patient''s dry weight is set correctly", "Cool dialysate is used", "Ultrafiltration is low", "Ultrafiltration is high and the patient takes antihypertensives before dialysis"]'::jsonb, 3, 'Review dry weight and timing of BP drugs.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 11, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Diffusion across the dialyser membrane is increased by:', '["Smaller membrane surface area", "A larger concentration gradient and higher blood and dialysate flows", "Stopping dialysate flow", "Lower blood flow rates"]'::jsonb, 1, 'Countercurrent flow keeps the gradient high.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 12, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Pyrogenic reactions during dialysis present with:', '["Facial palsy", "Bradycardia only", "Low blood sugar", "Fever and rigors during the session"]'::jsonb, 3, 'They are caused by contaminated water or equipment.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 13, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Interdialytic weight gain is calculated as:', '["Post-dialysis weight minus dry weight", "Weight at birth minus current weight", "Pre-dialysis weight minus the last post-dialysis weight", "Height minus weight"]'::jsonb, 2, 'It shows fluid accumulated between sessions.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 14, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Hepatitis B–positive patients on haemodialysis should be:', '["Given the same dialyser as others", "Refused dialysis", "Dialysed in isolation with dedicated machines and staff", "Dialysed anywhere in the unit"]'::jsonb, 2, 'Dialyser reuse is not allowed for them.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 15, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Low venous pressure alarm during dialysis may indicate:', '["Disconnection or dislodged venous needle", "High blood flow", "Normal dialysis", "Clotting in the venous chamber"]'::jsonb, 0, 'This can cause rapid blood loss; check at once.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 16, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Restless, confused patient with headache and vomiting at the first dialysis may have:', '["Dialysis disequilibrium syndrome", "Anaphylaxis", "Hypoglycaemia only", "Air embolism"]'::jsonb, 0, 'Prevent with short, gentle first sessions.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 17, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Aluminium contamination of dialysis water can cause:', '["Hyperkalaemia", "Dialysis dementia and bone disease", "Hypoglycaemia", "Haemolysis only"]'::jsonb, 1, 'Water quality must be tested regularly.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 18, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'An access aneurysm with shiny, thin skin and bleeding risk should be:', '["Massaged daily", "Covered with a tight bandage permanently", "Cannulated every session", "Reported urgently and not cannulated over the thin area"]'::jsonb, 3, 'Rupture can cause fatal bleeding.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 19, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'An arteriovenous graft differs from a fistula because it:', '["Is placed in the abdomen", "Uses synthetic tubing between artery and vein", "Uses only the patient''s own vein", "Needs no surgery"]'::jsonb, 1, 'Grafts are ready sooner but clot and infect more often.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 20, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Dialysis catheter lumens are locked between sessions with:', '["Potassium chloride", "Normal saline only, any volume", "Air", "Heparin or citrate lock solution of the exact lumen volume"]'::jsonb, 3, 'Aspirate the lock before the next use.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 21, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Exercises to help an AV fistula mature include:', '["Wearing a tight watch on that wrist", "Squeezing a soft ball with the fistula hand", "Sleeping on the fistula arm", "Keeping the arm in a tight sling"]'::jsonb, 1, 'Exercise increases blood flow and vein dilation.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 22, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Blood and dialysate flow in opposite directions in the dialyser (countercurrent) to:', '["Stop clotting", "Warm the blood", "Prevent air embolism", "Keep the concentration gradient high along the whole membrane"]'::jsonb, 3, 'This makes diffusion more efficient.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 23, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Reverse osmosis in a dialysis water treatment plant mainly removes:', '["Only heat from the water", "Only chlorine and chloramine", "Only visible particles and sand", "Dissolved salts, bacteria and endotoxins"]'::jsonb, 3, 'Carbon filters remove chlorine and chloramine before RO.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 24, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Central venous stenosis in dialysis patients is commonly caused by:', '["Arm exercises", "Previous central venous catheters, especially subclavian lines", "Phosphate binders", "Low-salt diet"]'::jsonb, 1, 'It causes arm swelling and access dysfunction.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 25, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Isolated ultrafiltration (without diffusion) is useful to:', '["Correct acidosis", "Lower potassium fast", "Remove fluid quickly with little hypotension", "Clear urea rapidly"]'::jsonb, 2, 'No dialysate flows during it.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 26, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Hard water syndrome during haemodialysis causes:', '["Bradycardia only", "Bleeding from the access", "Nausea, vomiting, hypertension and headache from high calcium", "Low blood sugar"]'::jsonb, 2, 'It results from failure of the water softener.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 27, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Before starting haemodialysis, all new patients should be screened for:', '["Only blood glucose", "Hepatitis B, hepatitis C and HIV", "Only blood group", "Malaria only"]'::jsonb, 1, 'Vaccinate against hepatitis B if not immune.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 28, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Dialysis adequacy is commonly measured monthly using:', '["Chest X-ray", "Daily weight only", "Pre- and post-dialysis urea to calculate URR or Kt/V", "Serum amylase"]'::jsonb, 2, 'Post-dialysis blood must be taken correctly.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 29, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Access recirculation occurs when:', '["Cleaned blood from the venous needle re-enters the arterial needle", "The patient lies flat", "The patient drinks too much water", "The dialyser is too large"]'::jsonb, 0, 'It reduces dialysis adequacy; check needle placement.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 30, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Patients are taught to check their fistula daily by:', '["Feeling the thrill and listening for the bruit", "Wearing a tight bracelet", "Pressing hard on it for 10 minutes", "Sleeping on it"]'::jsonb, 0, 'Report if the thrill is absent.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 31, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Disinfection of the dialysis machine is done:', '["Once a month", "After every patient, per the manufacturer''s instructions", "Only when visibly dirty", "Never"]'::jsonb, 1, 'Heat or chemical disinfection prevents cross-infection.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 32, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Buttonhole cannulation uses:', '["Sharp needles into scabbed holes without cleaning", "Random sites each time", "The same site and angle each time with blunt needles", "A new vein each week"]'::jsonb, 2, 'Strict asepsis is needed because infection risk is higher.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 33, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Signs of fistula infection include:', '["Cool, pale fingers only", "A strong thrill and bruit", "Normal skin", "Redness, warmth, swelling and pus at the access site"]'::jsonb, 3, 'Do not cannulate an infected site; inform the doctor.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 34, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Cool dialysate (35.5–36 °C) helps prevent intradialytic hypotension because it:', '["Reduces bleeding", "Removes more urea", "Causes vasoconstriction and better vascular stability", "Kills bacteria"]'::jsonb, 2, 'Patients may feel cold.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 35, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'A clotted dialyser after a session is recognised by:', '["Dark streaks in the fibres and rising pressures", "Clear, white fibres", "Normal transmembrane pressure", "Falling venous pressure"]'::jsonb, 0, 'Review anticoagulation and blood flow.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 36, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Home haemodialysis requires:', '["A hospital admission every week", "Training of the patient and carer, water treatment and support", "No training at all", "No machine"]'::jsonb, 1, 'It allows longer and more frequent sessions.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 37, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Which patient would require the least amount of, or no, heparin anticoagulation during hemodialysis?', '["A patient with a normal platelet count and coagulation studies", "A patient with a well-functioning arteriovenous fistula", "A patient with no bleeding risk undergoing routine outpatient dialysis", "A patient who is actively bleeding or recently had surgery"]'::jsonb, 3, 'In patients with active bleeding, recent surgery, or high bleeding risk, dialysis is often performed with minimal or no heparin, or regional citrate anticoagulation, to avoid worsening hemorrhage.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 38, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Most appropriate treatment for clotted haemodialysis shunt?', '["Irrigate with heparinized saline", "Systemic urokinase", "Broad-spectrum antibiotics", "Consult a vascular surgeon"]'::jsonb, 3, 'A clotted shunt or fistula needs urgent referral to the vascular surgeon (or interventional radiology) for thrombectomy. Do not force-irrigate it.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 39, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Uremic pericarditis, a potential complication of untreated or inadequately dialyzed end-stage renal disease, is classically treated by:', '["Intensified or urgent dialysis", "Fluid restriction only, with no change to dialysis", "High-dose diuretics", "Beta-blockers alone"]'::jsonb, 0, 'Uremic pericarditis is an indication for intensified or emergent dialysis, since it results from accumulated uremic toxins; NSAIDs are typically avoided due to increased risk of hemorrhagic pericardial effusion in these often-anticoagulated patients.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 40, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'Assessment of a functioning arteriovenous (AV) fistula should include palpating for a:', '["Cold, pale extremity", "Thrill and auscultating for a bruit", "Bounding pulse only", "Absent pulse distally as a normal finding"]'::jsonb, 1, 'A patent AV fistula produces a palpable thrill and an audible bruit from turbulent blood flow; absence of either suggests possible thrombosis requiring urgent evaluation.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 41, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Clients with chronic obstructive bronchitis are given diuretic therapy. Which of the following reasons best explains why?', '["Reducing fluid volume improves clients’ mobility.", "Reducing fluid volume improves respiratory function.", "Restricting fluid volume reduces sputum production.", "Reducing fluid volume reduces oxygen demand."]'::jsonb, 3, 'In chronic bronchitis with cor pulmonale, diuretics reduce fluid overload and so ease cardiac workload and oxygen demand.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 42, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'In chronic severe hyponatraemia, sodium should not be raised by more than about:', '["20–25 mmol/L in the first 24 hours", "15 mmol/L in the first hour", "8–10 mmol/L in the first 24 hours", "2 mmol/L in the first week"]'::jsonb, 2, 'Over-rapid correction causes osmotic demyelination (central pontine myelinolysis).', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 43, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A nurse overriding a hesitant colleague''s objection to start immediate CPR during a cardiac arrest is an example of which conflict style?', '["Avoiding", "Accommodating", "Competing", "Collaborating"]'::jsonb, 2, 'High assertiveness with low cooperation — pursuing the necessary action decisively — is appropriate in a genuine time-critical emergency.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 44, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Acute adrenal (Addisonian) crisis is a life-threatening emergency best managed with immediate administration of which agent, alongside aggressive fluid resuscitation?', '["IV insulin", "IV hydrocortisone", "Oral fludrocortisone only", "IV levothyroxine"]'::jsonb, 1, 'Adrenal crisis requires immediate IV stress-dose hydrocortisone (which also has mineralocorticoid activity at high doses) plus aggressive isotonic saline and dextrose administration to correct hypotension and hypoglycemia; delay in treatment can be fatal.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 45, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'By KDIGO criteria, AKI stage 3 includes urine output below 0.3 mL/kg/h for 24 hours or:', '["A single raised urea level", "Serum creatinine 3 times the baseline", "Urine output 0.5 mL/kg/h for 6 hours", "Serum creatinine 1.2 times the baseline"]'::jsonb, 1, 'Stage 3 also includes anuria for 12 hours or starting renal replacement therapy.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 46, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Renal autoregulation maintains a relatively constant glomerular filtration rate across which approximate range of mean arterial pressure?', '["60-80 mmHg", "80-180 mmHg", "40-60 mmHg", "180-220 mmHg"]'::jsonb, 1, 'Through myogenic and tubuloglomerular feedback mechanisms, renal blood flow and GFR remain relatively stable across a MAP range of roughly 80-180 mmHg; below this, renal perfusion falls sharply.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 47, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'During cardiac arrest, which mode of intra-aortic balloon pump (IABP) can provide very effective perfusion in conjunction with external compression?', '["Pacer A", "Internal", "ECG", "Pressure"]'::jsonb, 3, 'During CPR, ECG is unreliable due to compression artifact, so the IABP is switched to a pressure trigger.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 48, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which electrolyte abnormality pattern is classically associated with primary adrenal insufficiency due to combined cortisol and aldosterone deficiency?', '["Hypernatremia and hypokalemia", "Hyponatremia and hypokalemia", "Hyponatremia and hyperkalemia", "Normal sodium with hyperkalemia only"]'::jsonb, 2, 'Aldosterone deficiency causes renal sodium wasting and potassium retention (hyponatremia, hyperkalemia), while cortisol deficiency contributes to hyponatremia via impaired free water clearance and loss of cortisol''s normal permissive vascular effects.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 49, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Adult anaphylaxis is first treated with IM adrenaline at a dose of:', '["0.5 mg (0.5 mL of 1:1000) into the anterolateral thigh", "0.05 mg (0.5 mL of 1:10,000) subcutaneously", "1 mg (10 mL of 1:10,000) intramuscularly in the deltoid", "5 mg (5 mL of 1:1000) IV push"]'::jsonb, 0, 'Repeat after 5 minutes if there is no improvement. Then give oxygen, fluids and call for help.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 50, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient with hyperkalemia has peaked T waves. After calcium gluconate, which drug shifts potassium intracellularly?', '["Furosemide", "Albuterol", "Fludrocortisone", "Sodium polystyrene"]'::jsonb, 1, 'Albuterol (β2-agonist) shifts K⁺ into cells. Sodium polystyrene increases excretion but is slow-acting.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 51, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Etomidate is useful in shocked patients because of cardiovascular stability, but it can cause:', '["Malignant hyperthermia", "Severe bronchospasm", "Raised intracranial pressure", "Adrenal suppression"]'::jsonb, 3, 'It inhibits cortisol synthesis.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 52, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'For an adult having elective surgery, current fasting guidelines usually allow clear fluids up to:', '["24 hours before induction", "2 hours before induction", "12 hours before induction", "30 minutes before induction"]'::jsonb, 1, 'The ''6-4-2'' style rule: light meal/formula 6 hours, breast milk 4 hours, clear fluids 2 hours. Prolonged fasting causes dehydration, hypoglycaemia and discomfort without reducing aspiration risk.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 53, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A 55 year old male patient is admitted with a massive GI bleed. The patient is at risk for what type of acute kidney injury?', '["Post-renal", "Pre-renal", "Intra-renal", "Intrinsic renal"]'::jsonb, 1, 'Massive GI bleeding causing hypovolaemia is a classic pre-renal cause of AKI.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 54, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which electrolyte would the nurse identify as the major electrolyte responsible for determining the concentration of the extracellular fluid?', '["Phosphate", "Bicarbonate", "Sodium", "Chloride"]'::jsonb, 2, 'Sodium is the main extracellular cation and sets ECF osmolality and concentration.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 55, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Hyperphosphataemia is a common electrolyte disturbance in patients with:', '["Diabetes insipidus", "Primary hyperaldosteronism", "SIADH", "Chronic kidney disease"]'::jsonb, 3, 'Reduced renal phosphate excretion in chronic kidney disease commonly leads to hyperphosphataemia, which also contributes to secondary hyperparathyroidism and vascular calcification over time.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 56, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'The intra-aortic balloon pump inflates during:', '["Diastole, improving coronary flow", "Only during cardiac arrest", "Systole, increasing the afterload", "Both phases equally throughout"]'::jsonb, 0, 'It deflates just before systole to reduce afterload.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 57, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'CVP that is low most likely indicates the need for:', '["No action needed", "Fluid administration", "Diuretics", "Vasoconstrictors only"]'::jsonb, 1, 'A low central venous pressure suggests the patient is relatively underfilled and needs more fluid.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 58, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient in PACU after major abdominal surgery has a rising heart rate, falling BP and cool peripheries. The first step is:', '["Discharge the patient to the ward for routine observations", "Give a sedative and wait to see if the vital signs settle", "Look for bleeding, give oxygen and IV fluid, call the surgeon", "Reduce the IV fluids to protect the heart from overload, and observe"]'::jsonb, 2, 'Hypovolaemia from bleeding is the commonest cause.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 59, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A post-operative patient with high-flow suction on a nasogastric tube in PACU should be monitored for:', '["Polycythaemia caused by the suction pump", "Rapid weight gain from fluid retention in the abdominal wall", "Hyperglycaemia only, from the stress response", "Fluid and electrolyte losses, mainly potassium"]'::jsonb, 3, 'Record NG output on the fluid chart.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 60, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Potassium is most abundant in which compartment?', '["Extracellular", "Intracellular", "Interstitial", "Intravascular"]'::jsonb, 1, 'About 98% of the body''s potassium is intracellular (about 140 mmol/L inside cells vs 3.5–5 outside).', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 61, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'The target haematocrit (HCT) during resuscitation for variceal bleeding is:', '["25–30%", "45–50%", "10–15%", "60–65%"]'::jsonb, 0, 'This moderate target avoids both under-resuscitation and over-transfusion, which can raise portal pressure and worsen variceal bleeding.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 62, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'The most common causes of anaphylaxis during anaesthesia are:', '["Normal saline and dextrose", "Sterile water and lubricants", "Oxygen and nitrous oxide from the anaesthetic machine", "Neuromuscular blockers, antibiotics and chlorhexidine"]'::jsonb, 3, 'Treat with adrenaline, fluids, oxygen and stop the trigger.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 63, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A gum elastic bougie is used during intubation to:', '["Guide the tube when the glottis is only partly seen", "Suction secretions from the trachea", "Measure the pressure inside the endotracheal tube cuff", "Replace the laryngoscope blade"]'::jsonb, 0, 'The tube is railroaded over the bougie into the trachea.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 64, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'For septic shock that stays refractory despite fluids and vasopressors, guidelines suggest:', '["IV hydrocortisone about 200 mg per day", "IV dexamethasone 40 mg as a single bolus", "IV methylprednisolone 1 g daily for 3 days", "Oral prednisolone 5 mg daily"]'::jsonb, 0, 'Hydrocortisone shortens shock duration. Monitor glucose.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 65, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'The safest IV fluid for thyroidectomy patient post-op is:', '["Plasma", "Normal saline", "Dextrose 5%", "Ringer''s lactate with calcium"]'::jsonb, 1, 'Normal saline avoids the calcium content found in some other IV fluids, which could worsen hypercalcaemia risk.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 66, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Clear fluids before elective surgery in children are usually allowed up to:', '["6 hours before anaesthesia", "12 hours before anaesthesia", "1 hour before anaesthesia (per many current guidelines)", "Only up to 6 hours before anaesthesia, the same as for solid food"]'::jsonb, 2, 'Breast milk is allowed up to 4 hours and formula up to 6 hours.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 67, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which of following trigger in the IABP machine should be used for a patient during Cardiac Pulmonary Resuscitation (CPR)?', '["Pacer A", "Pressure", "ECG", "Internal Trigger"]'::jsonb, 1, 'Pressure triggering is used during CPR since chest compressions make ECG triggering unreliable.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 68, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient is undergoing cardiac catheterization. Which of the following sensations reported by the patient during the procedure has the highest priority?', '["Chest pain", "Urge to cough", "Warm, flushed feeling", "Pressure at the insertion site"]'::jsonb, 0, 'Chest pain during catheterisation could signal ischaemia or complication — always the highest-priority symptom.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 69, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'High level of potassium is termed _____', '["Hyper-potassium syndrome", "Hypokalemia", "Hyperkalemia", "Hyper- potassiumaemia"]'::jsonb, 2, 'High potassium is hyperkalaemia.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 70, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'By Sepsis-3, septic shock is sepsis needing vasopressors to keep MAP ≥65 mmHg and:', '["A positive blood culture result from the lab", "A white cell count above 12 × 10⁹/L on admission", "Lactate above 2 mmol/L despite adequate fluids", "A temperature above 38 °C for over an hour"]'::jsonb, 2, 'Hospital mortality of septic shock is above 40%.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 71, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient with syndrome of inappropriate ADH secretion (SIADH) causing symptomatic hyponatremia is treated with fluid restriction. Which additional mechanism-based therapy directly antagonizes ADH''s renal action?', '["Loop diuretics as monotherapy without sodium replacement", "Exogenous desmopressin (DDAVP)", "IV isotonic saline as first-line for all severities", "Vasopressin receptor antagonists (vaptans)"]'::jsonb, 3, 'Vaptans (e.g., tolvaptan, conivaptan) selectively block V2 receptors in the renal collecting duct, directly antagonizing ADH''s water-retaining effect and promoting aquaresis (electrolyte-free water excretion) to correct hyponatremia in SIADH.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 72, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A bispectral index (BIS) value of 40–60 during general anaesthesia indicates:', '["The patient is fully awake", "Too deep anaesthesia needing reversal", "An adequate depth of anaesthesia", "Brain death"]'::jsonb, 2, 'It may help reduce awareness in TIVA.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 73, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'The complication rate for partial nephrectomy is approximately:', '["90–100%", "50–60%", "1–2%", "15–25%"]'::jsonb, 3, 'This is a clinically significant rate, with bleeding, infection, and urinary leak being the most common complications.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 74, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient with a very dry mouth, skin, and mucous membranes is diagnosed with dehydration. Which intervention should the nurse perform when caring for a patient diagnosed with fluid volume deficit?', '["Assessing urinary intake and output", "Obtaining the clients weight weekly at different times of the day.", "Maintaining I V therapy at the keep vein open rate.", "Monitoring arterial blood gas ABG results"]'::jsonb, 0, 'Tracking intake and output directly monitors fluid balance status in dehydration.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 75, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient in the ICU develops signs of sepsis postoperatively. What intervention should the nurse prioritize?', '["Checking vital signs frequently", "Administering pain medication", "Initiating intravenous fluids", "Providing oxygen therapy"]'::jsonb, 2, 'IV fluid resuscitation is a priority in postoperative sepsis to support perfusion, alongside prompt antibiotics and source control.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 76, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'When administering a TPN solution, a nurse must verify that it contains all the prescribed components. What are the three main macronutrients provided in TPN?', '["Sodium, potassium, and chloride", "Carbohydrates, proteins, and fats", "Dextrose, amino acids, and lipids", "Water, electrolytes, and vitamins"]'::jsonb, 2, 'The three main macronutrient components of TPN are Dextrose (for carbohydrates), Amino Acids (for proteins), and Lipids (for fats). Water, electrolytes, and vitamins are also essential but are not considered macronutrients.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 77, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Nutritional support for critically ill patient on admission should begin as soon as patient is ------------------------- stable.', '["Physiologically", "Metabolically", "Haemodynamically", "Anatomically"]'::jsonb, 2, 'Nutritional support should begin once the patient is haemodynamically stable.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 78, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'In severe acute pancreatitis, the preferred nutrition route when tolerated is:', '["Early enteral feeding (nasogastric or nasojejunal)", "Nil by mouth with no feeding for 2 weeks", "Oral fatty meals to stimulate the pancreas", "Routine parenteral nutrition from day one"]'::jsonb, 0, 'Enteral feeding protects the gut barrier and lowers infection.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 79, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Which of the following is an example of an anthropometric measurement used in nutritional assessment?', '["White blood cell count", "Mid-upper arm circumference", "Serum albumin level", "C-reactive protein level"]'::jsonb, 1, 'Anthropometric measurements assess body size and composition and include height, weight, BMI, mid-upper arm circumference, and triceps skinfold thickness.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 80, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'In COPD patients, excessive carbohydrate feeding can:', '["Lower the PaCO₂ by improving ventilation", "Improve weaning by giving energy to the muscles", "Reduce the oxygen consumption of the body", "Raise CO₂ production and worsen respiratory failure"]'::jsonb, 3, 'Avoid overfeeding.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 81, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'The most effective natural protection against stress ulceration in ICU is:', '["Keeping the patient nil by mouth until extubation", "Giving liquid antacids every hour by NG tube", "Prolonged fasting before each procedure", "Early enteral feeding and good splanchnic perfusion"]'::jsonb, 3, 'Gut perfusion and nutrition protect the mucosa.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 82, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'The Subjective Global Assessment (SGA) classifies nutritional status using:', '["History (weight loss, intake, GI symptoms, function) plus examination", "Body mass index alone, calculated from height and weight", "Serum albumin alone, measured on admission and weekly", "Blood glucose and HbA1c measured on the first ICU day"]'::jsonb, 0, 'Patients are graded A (well nourished), B (moderate) or C (severely malnourished).', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 83, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'The electrolyte abnormality most typical of refeeding syndrome in a starved ICU patient is:', '["Hypercalcaemia", "Hypernatraemia", "Hypophosphataemia", "Hyperkalaemia"]'::jsonb, 2, 'Insulin release drives phosphate, potassium and magnesium into cells. Start feeding slowly and replace phosphate, with thiamine first.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 84, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Calorie needs of a critically ill adult in the early phase are about:', '["100 kcal/kg/day", "5 kcal/kg/day", "50 kcal/kg/day", "20–25 kcal/kg/day"]'::jsonb, 3, 'Overfeeding causes hyperglycaemia and increases CO₂ production.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 85, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'A patient on TPN develops fever and rigors. The nurse suspects:', '["Refeeding syndrome from the TPN", "A normal reaction to the lipids", "Catheter-related bloodstream infection", "Dehydration from the glucose load"]'::jsonb, 2, 'Take cultures from line and periphery.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 86, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'The nurse is preparing to administer TPN. What is the most important nursing responsibility before starting the infusion?', '["Checking the patient''s blood pressure", "Administering a dose of insulin", "Documenting the patient''s height and weight", "Verifying the TPN solution with another nurse"]'::jsonb, 3, 'TPN is a high-risk medication due to its complexity. A critical safety measure is to have a second nurse independently verify the TPN solution against the provider''s order to prevent medication errors.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 87, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'A patient on TPN is showing signs of fluid volume excess. Which of the following nursing interventions is most appropriate?', '["Monitoring the patient''s blood glucose levels", "Notifying the provider to decrease the fluid rate", "Increasing the TPN infusion rate", "Administering a bolus of intravenous fluids"]'::jsonb, 1, 'If a patient shows signs of fluid volume excess (e.g., crackles, edema), the nurse should immediately notify the provider so the TPN infusion rate or the fluid components can be adjusted to prevent further complications like heart failure.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 88, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'In toxic epidermal necrolysis, more than 30% of the body surface is detached. ICU care is similar to:', '["Major burns: fluids, warmth, wound care, infection control, nutrition", "Cellulitis: oral antibiotics and elevation of the limbs", "Eczema: emollients and topical steroids at home", "A simple allergy: antihistamines and observation on the ward"]'::jsonb, 0, 'Stop the culprit drug. SCORTEN predicts mortality.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 89, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Enteral feeding is preferred to parenteral because it:', '["It avoids every risk of aspiration completely", "It is always more accurate in calorie delivery", "It maintains gut integrity with fewer infections", "It needs no monitoring once it has started"]'::jsonb, 2, 'TPN is reserved for when the gut cannot be used.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 90, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Nutritional deficiencies can occur postoperatively in the ICU. Which vitamin deficiency is commonly seen in surgical patients?', '["Vitamin D", "Vitamin C", "Vitamin A", "Vitamin B12"]'::jsonb, 3, 'Vitamin B12 and other nutrient deficiencies are recognised risks after major surgery, particularly with reduced intake or malabsorption.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 91, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'A patient with hepatic encephalopathy needs nutrition. The current approach is:', '["Normal protein, with branched-chain amino acids if intolerant", "Complete protein restriction until the ammonia normalises", "A high-fat, carbohydrate-free diet to reduce ammonia", "Fasting until the encephalopathy has resolved fully"]'::jsonb, 0, 'Protein restriction worsens malnutrition; lactulose and rifaximin manage ammonia.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 92, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Refeeding syndrome after starting feeds in a malnourished ICU patient causes:', '["High phosphate, high potassium and high urea", "High blood glucose with normal electrolytes", "Low phosphate, low potassium and low magnesium", "High calcium, high sodium and high chloride"]'::jsonb, 2, 'Start feeds slowly, give thiamine and monitor electrolytes.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 93, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'A patient''s TPN is discontinued. What is the most appropriate nursing action to prevent a rapid drop in blood glucose (hypoglycemia)?', '["Hanging a bag of D10W (10% Dextrose in Water)", "Administering a dose of insulin", "Immediately capping the central line", "Decreasing the TPN rate to half for 24 hours"]'::jsonb, 0, 'When TPN is abruptly discontinued, the pancreas, which has been producing a high level of insulin to handle the concentrated glucose, can continue to produce too much insulin, leading to rebound hypoglycemia. Hanging D10W prevents this by providing a temporary glucose source.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 94, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'A patient with hypophosphatemia is receiving TPN. Which intervention prevents refeeding syndrome?', '["Start TPN at full calories", "Supplement with IV phosphorus", "Add extra potassium", "Restrict glucose in TPN"]'::jsonb, 1, 'Refeeding syndrome causes hypophosphatemia; preemptive supplementation and gradual calorie increase are key.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 95, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Parenteral nutrition via a central line requires:', '["Strict asepsis, a dedicated lumen and glucose checks", "No need for blood glucose monitoring", "Sharing the lumen with blood transfusions", "Hanging each bag for up to 72 hours"]'::jsonb, 0, 'Line infection and hyperglycaemia are common complications.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 96, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Hyperglycaemia during TPN is managed by:', '["Insulin and adjusting the glucose content", "Stopping all nutrition immediately", "Ignoring glucose levels while on TPN", "Giving extra dextrose to the TPN"]'::jsonb, 0, 'Target glucose about 6–10 mmol/L.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 97, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Enteral feeding should be started in a critically ill patient:', '["Only after two weeks of IV fluids alone", "Only after the patient has been extubated", "Only when the patient asks for food", "Within 24–48 hours, once haemodynamically stable"]'::jsonb, 3, 'Early feeding maintains gut integrity.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 98, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'Gastric residual volumes in an enterally fed ICU patient are:', '["Never checked in any enterally fed ICU patient", "Only one sign of tolerance, alongside abdominal examination", "The only reliable measure of feed tolerance in ICU", "Used to calculate the patient''s daily calorie needs"]'::jsonb, 1, 'Feeds are not stopped for moderate residuals without other signs.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 99, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'To reduce aspiration during enteral feeding, the patient should be:', '["Head elevated 30–45 degrees", "Prone without support", "Head-down tilt", "Flat on the back"]'::jsonb, 0, 'Check tolerance and gastric distension.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 100, 'Nephrology Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'The nurse is preparing to change the dressing on a central line used for TPN. What type of dressing is most appropriate?', '["An occlusive dressing with petroleum jelly", "A bandage with adhesive tape", "A transparent, semipermeable membrane dressing", "A simple gauze dressing"]'::jsonb, 2, 'A transparent dressing allows the nurse to visualize the insertion site for signs of infection without removing the dressing. It also provides a barrier against external contaminants while allowing the skin to breathe.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(3, 1, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'A client who has managed a chronic illness for many years tells the nurse, ''I''ve learned so much about myself through this journey, and I feel I''ve grown into the best version of myself.'' This statement best reflects which level of Maslow''s hierarchy?', '["Self-actualization needs", "Self-esteem needs", "Safety and security needs", "Physiological needs"]'::jsonb, 0, 'Self-actualization, the highest level in Maslow''s hierarchy, involves realizing one''s fullest potential, personal growth, and self-fulfillment — reflected in this client''s sense of personal growth through adversity.', 'GST 401 · Applied Psychology & Sociology'),
(3, 2, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Abraham Maslow''s hierarchy of needs is typically depicted as a pyramid with which level at the very base, representing the most fundamental needs?', '["Self-actualization needs", "Love and belonging needs", "Safety and security needs", "Physiological needs"]'::jsonb, 3, 'Physiological needs, such as oxygen, food, water, and elimination, form the base of Maslow''s pyramid because they must generally be met first to sustain life before higher-level needs can be addressed.', 'GST 401 · Applied Psychology & Sociology'),
(3, 3, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'A nurse is caring for four clients simultaneously. Which client''s need should the nurse prioritize FIRST according to Maslow''s hierarchy of needs?', '["A client worried about being discharged without family support", "A client requesting a chaplain visit for spiritual support", "A client expressing embarrassment about needing help with bathing", "A client with an oxygen saturation of 84% on room air"]'::jsonb, 3, 'A critically low oxygen saturation represents an urgent physiological need (oxygenation) that takes priority over safety, love/belonging, and esteem needs according to Maslow''s hierarchy.', 'GST 401 · Applied Psychology & Sociology'),
(3, 4, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'One of the following is called the positive stress.', '["Eustress", "Worries", "Happiness", "Anxiety"]'::jsonb, 0, 'Eustress is the recognised term for positive, beneficial stress.', 'GST 401 · Applied Psychology & Sociology'),
(3, 5, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'A client recovering from a mastectomy tells the nurse, ''I''m worried my husband won''t find me attractive anymore and that we''ll grow apart.'' This concern is most directly related to which level of Maslow''s hierarchy?', '["Safety and security needs", "Self-actualization needs", "Physiological needs", "Love and belonging needs"]'::jsonb, 3, 'Concerns about intimacy and connectedness within a significant relationship correspond to the love and belonging level of Maslow''s hierarchy.', 'GST 401 · Applied Psychology & Sociology'),
(3, 6, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'The method and process of facilitating the peaceful ending of a conflict is called:', '["Conflict resolution", "Fight", "Psychological trauma", "Conflict"]'::jsonb, 0, 'Conflict resolution is the process of bringing a conflict to a peaceful end.', 'GST 401 · Applied Psychology & Sociology'),
(3, 7, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Health belief model suggests that people take health action when they:', '["Are told to without explanation", "Believe they are at risk and the benefits outweigh the barriers", "Have no knowledge of the illness", "Have no symptoms or risk"]'::jsonb, 1, 'It helps plan patient education.', 'GST 401 · Applied Psychology & Sociology'),
(3, 8, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Behavioural Science is defined by the American Psychological Association as:', '["A discipline in which humans relate with their environment.", "Subject of studying human behaviours.", "Discipline that uses systemic observation and experimentation in the scientific study of human and non-human actions and reactions.", "Discipline of applied behavioural analysis which involves applying behavioural principles in practice setting."]'::jsonb, 2, 'APA defines behavioural science as the systematic scientific study of human/non-human actions and reactions.', 'GST 401 · Applied Psychology & Sociology'),
(3, 9, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Kubler-Ross''s stages of grief are:', '["Anger, denial, depression, acceptance, bargaining", "Denial, anger, bargaining, depression and acceptance", "Acceptance, denial, anger, depression, bargaining", "Shock, surprise, anger, acceptance, joy"]'::jsonb, 1, 'Not all patients go through every stage in order.', 'GST 401 · Applied Psychology & Sociology'),
(3, 10, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Erikson''s stage for adolescents is:', '["Trust versus mistrust", "Industry versus inferiority", "Identity versus role confusion", "Integrity versus despair"]'::jsonb, 2, 'Body image after surgery is especially important to teenagers.', 'GST 401 · Applied Psychology & Sociology'),
(3, 11, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'The ''sick role'' described by Parsons includes the right to be excused from normal duties and the duty to:', '["Stay ill as long as possible", "Refuse all treatment", "Seek help and try to get well", "Hide the illness"]'::jsonb, 2, 'Society expects the sick person to cooperate with care.', 'GST 401 · Applied Psychology & Sociology'),
(3, 12, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'A client has multiple identified nursing diagnoses. Which method is commonly used to prioritize these diagnoses?', '["Client''s personal preference alone, without clinical judgment", "Alphabetical order of the diagnostic labels", "Maslow''s Hierarchy of Needs, addressing physiological and safety needs first", "The order in which they were identified during assessment"]'::jsonb, 2, 'Maslow''s Hierarchy of Needs is a common framework for prioritizing nursing diagnoses, with physiological and safety needs typically addressed first.', 'GST 401 · Applied Psychology & Sociology'),
(3, 13, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Non-verbal communication includes:', '["Emails", "Facial expression, posture and eye contact", "Written reports only", "Telephone calls only"]'::jsonb, 1, 'It often carries more meaning than words.', 'GST 401 · Applied Psychology & Sociology'),
(3, 14, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Regression is when a patient:', '["Blames other people for own feelings", "Becomes more mature and independent", "Channels feelings into useful activity", "Returns to behaviour of an earlier stage"]'::jsonb, 3, 'Common in children and stressed adults.', 'GST 401 · Applied Psychology & Sociology'),
(3, 15, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Effective communication with an anxious patient involves:', '["Interrupting the patient to save time", "Active listening, empathy and clear explanation", "Avoiding eye contact to reduce tension", "Using medical jargon to sound expert"]'::jsonb, 1, 'Nonverbal cues are important.', 'GST 401 · Applied Psychology & Sociology'),
(3, 16, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Body image changes after surgery such as mastectomy or stoma may cause:', '["Grief, low self-esteem and depression", "Improved mood and confidence only", "Increased self-esteem in every case", "No emotional effect at all"]'::jsonb, 0, 'Counselling and support groups help.', 'GST 401 · Applied Psychology & Sociology'),
(3, 17, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'A hospitalized client repeatedly asks the nurse to keep the bed rails up and the call light within reach, expressing fear of falling. This behavior is best explained by which level of Maslow''s hierarchy?', '["Love and belonging needs", "Self-actualization needs", "Safety and security needs", "Physiological needs"]'::jsonb, 2, 'Concerns about physical safety and protection from harm, such as fear of falling, correspond to the safety and security level of Maslow''s hierarchy, which follows physiological needs.', 'GST 401 · Applied Psychology & Sociology'),
(3, 18, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'A client who is newly diagnosed with a colostomy expresses distress, saying, ''I don''t feel like myself anymore; I feel disfigured.'' This response falls primarily within which of Roy''s adaptive modes?', '["Role function mode", "Self-concept/group identity mode", "Physiological-physical mode", "Interdependence mode"]'::jsonb, 1, 'Concerns about body image and personal identity following a change such as a colostomy fall within the self-concept/group identity mode, which addresses the person''s beliefs and feelings about the self, including body image.', 'GST 401 · Applied Psychology & Sociology'),
(3, 19, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Maslow''s self-actualisation refers to:', '["Realising one''s full potential", "Feeling safe and secure", "Meeting basic bodily needs", "Being loved and accepted"]'::jsonb, 0, 'It is the top of the hierarchy.', 'GST 401 · Applied Psychology & Sociology'),
(3, 20, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Displacement means:', '["Behaving the opposite of one''s feelings", "Redirecting feelings onto a safer target", "Blocking memories completely", "Making excuses for behaviour"]'::jsonb, 1, 'E.g. shouting at the nurse after bad news from the doctor.', 'GST 401 · Applied Psychology & Sociology'),
(3, 21, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'A nurse is organizing assessment data using Maslow''s Hierarchy of Needs. Which finding would be prioritized at the most basic (foundational) level?', '["Client expresses low self-esteem", "Client reports feeling isolated from friends", "Client has an oxygen saturation of 84% on room air", "Client is worried about returning to work"]'::jsonb, 2, 'Maslow''s hierarchy places physiological needs, such as oxygenation, at the foundational level, taking priority over psychosocial or self-esteem needs.', 'GST 401 · Applied Psychology & Sociology'),
(3, 22, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Rationalisation is:', '["Acting like a child", "Forgetting a painful event", "Refusing to believe a diagnosis", "Giving logical-sounding excuses for unacceptable behaviour"]'::jsonb, 3, 'It protects self-esteem.', 'GST 401 · Applied Psychology & Sociology'),
(3, 23, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Culture influences perioperative care because:', '["Culture has no effect on care in the theatre", "Only the surgeons'' culture affects patient care", "Beliefs about illness, blood, pain and modesty differ", "All patients share exactly the same beliefs"]'::jsonb, 2, 'Culturally sensitive care improves trust.', 'GST 401 · Applied Psychology & Sociology'),
(3, 24, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'A patient is admitted to the ICU following a suicide attempt by drug overdose. Once medically stabilised, the nurse''s priority alongside physical care is to:', '["Assess psychiatric risk, ensure a safe environment, and involve mental health/psychiatric services", "Focus exclusively on physical recovery with no psychological assessment", "Discharge the patient as soon as vital signs normalise, with no further assessment", "Avoid discussing the event with the patient entirely"]'::jsonb, 0, 'Care after a suicide attempt must include psychiatric risk assessment, ensuring a safe environment (e.g. removing means of harm), and timely involvement of mental health services, alongside physical stabilisation.', 'GST 401 · Applied Psychology & Sociology'),
(3, 25, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 401 · Applied Psychology & Sociology', 'Projection as a defence mechanism means:', '["Turning feelings into physical symptoms", "Refusing to accept reality", "Returning to childish behaviour", "Attributing one''s own unacceptable feelings to others"]'::jsonb, 3, 'E.g. an angry patient accusing the nurse of being angry.', 'GST 401 · Applied Psychology & Sociology'),
(3, 26, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'A nurse is teaching a group of nursing students about the history of computers. Which generation of computers is characterized by the use of vacuum tubes?', '["Second Generation", "Fourth Generation", "First Generation", "Third Generation"]'::jsonb, 2, 'The First Generation of computers, from 1940 to 1956, were characterized by the use of bulky and energy-inefficient vacuum tubes for circuitry. Second Generation computers used transistors, Third Generation used integrated circuits, and Fourth Generation used microprocessors.', 'GST 402 · Information Communication Technology'),
(3, 27, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'Electronic mail (e-mail) of patient information should be:', '["Sent to personal accounts because it is faster", "Printed and posted on the ward notice board", "Shared in staff group chats for quick advice", "Encrypted and sent only to authorised people"]'::jsonb, 3, 'Confidentiality laws apply to electronic communication.', 'GST 402 · Information Communication Technology'),
(3, 28, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'What does it mean to double click?', '["to press the left mouse button twice in quick succession.", "to press the left mouse button once", "to press the right mouse button once", "to press the right mouse button twice in quick succession."]'::jsonb, 0, 'Double-clicking means pressing the left mouse button twice in quick succession.', 'GST 402 · Information Communication Technology'),
(3, 29, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'Computers classified by size, from largest to smallest, are:', '["Laptop, desktop, tablet, mainframe", "Microcomputer, minicomputer, mainframe, supercomputer", "Server, router, modem, scanner", "Supercomputer, mainframe, minicomputer, microcomputer"]'::jsonb, 3, 'Most hospital desktops and laptops are microcomputers.', 'GST 402 · Information Communication Technology'),
(3, 30, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'RAM in a computer stands for:', '["Remote Access Module", "Rapid Access Machine", "Random Access Memory", "Read And Modify"]'::jsonb, 2, 'RAM is temporary working memory.', 'GST 402 · Information Communication Technology'),
(3, 31, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'What is five main components of a computer system?', '["Memory, Video card, Monitor, Software, Hardware", "CPU, CD-ROM, Mouse, Keyboard, Sound card", "Modem, Keyboard, Word Processor, Printer, Screen", "CPU, Memory, System bus, Input, Output"]'::jsonb, 3, 'The correct answer is: CPU, Memory, System bus, Input, Output.', 'GST 402 · Information Communication Technology'),
(3, 32, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'Data standardisation in nursing informatics is important because it:', '["It prevents any coding of nursing diagnoses", "It reduces the need for any documentation", "It lets data be compared, shared and analysed", "It increases the use of free-text descriptions"]'::jsonb, 2, 'NANDA, NIC and NOC are examples of standardised nursing terminologies.', 'GST 402 · Information Communication Technology'),
(3, 33, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'A CT scanner and ultrasound machine are examples of ICT in:', '["Treatment only", "Diagnosis", "Administration only", "Nursing education only"]'::jsonb, 1, 'Monitoring devices (oximeter, cardiac monitor) and treatment devices (infusion pumps, radiotherapy) are other categories.', 'GST 402 · Information Communication Technology'),
(3, 34, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'A nurse is explaining the units of data to a patient. The smallest unit of data in a computer is a:', '["Byte", "Bit", "Megabyte", "Kilobyte"]'::jsonb, 1, 'A bit (binary digit) is the most basic unit of information in computing and is a one or a zero. A byte is a group of 8 bits. The other options are larger units of data.', 'GST 402 · Information Communication Technology'),
(3, 35, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'A computer network within one hospital building is a:', '["Wide Area Network (WAN)", "Local Area Network (LAN)", "Metropolitan Area Network", "Personal Area Network"]'::jsonb, 1, 'A WAN links hospitals across cities; the internet is the largest WAN.', 'GST 402 · Information Communication Technology'),
(3, 36, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'Protecting electronic access to client data primarily relies on which of the following measures?', '["Disabling all data backups", "Printing all records to avoid computer use entirely", "Leaving all records openly accessible to any staff member for convenience", "User authentication (passwords/logins), access controls and audit trails"]'::jsonb, 3, 'Controlled access via authentication, role-based permissions and audit trails is a core safeguard for protecting confidential electronic client data.', 'GST 402 · Information Communication Technology'),
(3, 37, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'A nurse is setting up a new computer station in a clinic. Which of the following is considered an output device?', '["Scanner", "Mouse", "Microphone", "Printer"]'::jsonb, 3, 'An output device receives data from a computer. A printer produces a hard copy of a document. A mouse, scanner, and microphone are all input devices used to send information into the computer.', 'GST 402 · Information Communication Technology'),
(3, 38, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'Which one is application software?', '["Microsoft Word", "Windows XP", "Android 11", "Avast Antivirus"]'::jsonb, 0, 'Microsoft Word is application software. Windows and Android are operating systems; antivirus is utility software.', 'GST 402 · Information Communication Technology'),
(3, 39, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'Which one is NOT an input device?', '["Keyboard", "Monitor", "Scanner", "Mouse"]'::jsonb, 1, 'A monitor is an output device. Mouse, keyboard and scanner are input devices.', 'GST 402 · Information Communication Technology'),
(3, 40, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'GST 402 · Information Communication Technology', 'According to function, computers are classified as:', '["Automatic and manual", "Laptop, desktop and hand-held", "Electronic and battery-powered", "Analogue, digital and hybrid"]'::jsonb, 3, 'By function (how they process data), computers are analogue, digital or hybrid.', 'GST 402 · Information Communication Technology'),
(3, 41, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which of the following statements is true about stress management?', '["Only ‘a’ & ‘b’ are right", "Stress management helps us control our health in a positive sense", "Stress management is learning about the connection between mind and body", "Stress management teaches us to avoid all kinds of stress"]'::jsonb, 0, 'Stress management links mind and body and helps control health positively. Avoiding all stress is impossible and undesirable.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 42, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'The process of influencing and inspiring subordinate to achieve result is known as .......', '["(a). Management", "(b). Control", "(d). Administration", "(c). Leadership"]'::jsonb, 3, 'Influencing and inspiring others toward a goal defines leadership.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 43, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Must every leader be a manager and every manager be a leader?', '["Yes, always", "Only in the public sector", "No", "Only in hospitals"]'::jsonb, 2, 'Leadership and management overlap but are not the same: not every leader is a manager, and not every manager leads.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 44, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', '_________ principle of management states that there should be a place for everything and everything should be in its place.', '["Discipline", "Equity", "Order", "Esprit de corps"]'::jsonb, 2, 'The principle of order: a place for everything and everything in its place.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 45, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Planning that spans more than 5 years is:', '["Operational planning", "Tactical planning", "Long-term planning", "Medium-term planning"]'::jsonb, 2, 'Long-term (strategic) planning covers about 5 years or more.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 46, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which principle is an obligation to tell the truth and not lie or deceive the patient?', '["Justice", "Confidentiality", "Veracity", "Fidelity"]'::jsonb, 2, 'Veracity is the duty to tell the truth. Fidelity means keeping promises.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 47, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which of the following is in contrast with the guiding principles of trauma care?', '["Choice", "Collaboration", "Safety", "Reliability"]'::jsonb, 3, 'Trauma-informed care principles are safety, trustworthiness and transparency, peer support, collaboration, empowerment/voice/choice and cultural sensitivity. "Reliability" is not one of them.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 48, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'What is the full form of TQM?', '["Total quantity management", "Total quality measurement", "Typical quality management", "Total quality management"]'::jsonb, 3, 'TQM is Total Quality Management: a continuous, organisation-wide, customer-focused approach to quality.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 49, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'A nurse notices a suspicious lesion on a neonate but, knowing it could worsen, does not report it, and the baby is sent home and deteriorates. This is:', '["Advertent negligence", "Assault", "Battery", "Inadvertent negligence"]'::jsonb, 0, 'Advertent negligence: the carer knows the likely harmful consequence of omitting a required action and omits it anyway, e.g. noticing a lesion and not acting.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 50, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'A nurse manager observes that staff members are reluctant to report medication errors due to fear of punishment. Which culture should be promoted?', '["Just culture", "Competitive culture", "Blame culture", "Punitive culture"]'::jsonb, 0, 'A just culture, focused on system learning rather than blame, encourages honest reporting of medication errors.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 51, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', '__________ is a statement of expected results in numerical terms.', '["Forecast", "Budget", "Plan", "Estimate"]'::jsonb, 1, 'A budget states expected results in numerical (financial or quantitative) terms.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 52, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Material such as a full questionnaire or consent form used in a study is best placed in the:', '["Title page", "Results chapter", "Appendix", "Abstract"]'::jsonb, 2, 'Bulky supporting material that would clutter the main chapters is moved to the Appendix instead, often labelled by section (A, B, C).', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 53, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Divisional structure leads to conflict in', '["planning process.", "marketing management.", "motivation.", "resource allocation."]'::jsonb, 3, 'Divisions compete for shared resources, so divisional structures can cause conflict over resource allocation.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 54, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which of the following management functions are closely related?', '["planning and staffing", "planning and control", "planning and organizing", "staffing and control"]'::jsonb, 1, 'Planning and controlling are inseparable: plans set the standards that control measures against.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 55, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which of the following is an ethical principle that guides nursing practice?', '["Utilitarianism", "Care", "Autonomy", "Virtue"]'::jsonb, 2, 'Autonomy is one of the core ethical principles guiding nursing practice.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 56, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Scientific management is comprised of which of the following two elements?', '["Method study and work measurement", "Work measurement and job design", "Method study and job design", "Technology assessment and environmental design"]'::jsonb, 0, 'Scientific management (work study) is made up of method study and work measurement.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 57, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'A company that decides to decentralize its sales procedures is managing what change category?', '["Structure", "Competitors", "Technology", "People"]'::jsonb, 0, 'Decentralising procedures changes authority and reporting, which is a structural change.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 58, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', '___________ is the process of ensuring that actual results are in accordance with planned results.', '["Directing", "Planning", "Controlling", "Coordinating"]'::jsonb, 2, 'Controlling makes sure actual results match planned results.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 59, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which management function involves determining the goals and objectives of a nursing unit?', '["Directing", "Controlling", "Organizing", "Planning"]'::jsonb, 3, 'Setting the goals and objectives of a unit is the essence of the planning function.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 60, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'A document that lists the medical treatment a person chooses to refuse if unable to make decisions is the:', '["Informed consent", "Living will", "Durable power of attorney", "Advance directives"]'::jsonb, 1, 'A living will is the advance directive that lists the treatments a person chooses to refuse if they can no longer decide. A durable power of attorney names a proxy decision-maker instead.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 61, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'A nurse loves caring for the elderly. This represents her:', '["Respect", "Fidelity", "Dignity", "Values"]'::jsonb, 3, 'Values are a person''s deeply held beliefs about what is worthwhile, such as a love of caring for older people.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 62, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'The process of using resources to attain organisational goals is:', '["Management", "Leadership", "Delegation", "Supervision"]'::jsonb, 0, 'Management is using resources to attain organisational goals.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 63, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'In which respect does formal organisation differ from informal organisation?', '["Structuring", "Production process", "Financial procedure", "Purchasing"]'::jsonb, 0, 'Formal organisations have a deliberate structure with defined roles. Informal ones arise spontaneously from social relationships.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 64, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', '___________ denotes concentration of authority at the top level.', '["Coordination", "Delegation", "Centralisation", "Decentralisation"]'::jsonb, 2, 'Centralisation concentrates decision-making authority at the top.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 65, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Justice in healthcare ethics is primarily concerned with:', '["The law", "Equality and fairness", "Good and fairness", "Treating everyone the same"]'::jsonb, 1, 'Justice is about fairness and equity: fair, equal distribution of care and resources.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 66, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which ethical principle is demonstrated by respecting a competent patient''s informed refusal of treatment?', '["Autonomy", "Justice", "Beneficence", "Fidelity"]'::jsonb, 0, 'Respecting a competent patient''s informed refusal of treatment reflects the ethical principle of autonomy.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 67, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Organisation structure establishes relationships between', '["suppliers and customers.", "organisation and society.", "organisation and environment.", "people, work and resources."]'::jsonb, 3, 'Organisation structure links people, work and resources.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 68, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'A leadership style that does not take input from group members is:', '["Autocratic", "Democratic", "Participative", "Laissez-faire"]'::jsonb, 0, 'An autocratic leader makes decisions alone without input from the group.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 69, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'Which of the following statements is true', '["Too much stress is harmful", "In small quantities, stress is good", "Only a & b are right", "All stress is bad"]'::jsonb, 2, 'Moderate stress (eustress) can motivate. Too much stress is harmful.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 70, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 414 · Ethico-Legal Issues in Nephrology', 'A family disagrees with a DNR order for a patient with metastatic lung cancer. The nurse involves:', '["Hospital security", "Ethics committee", "Risk management", "Social services"]'::jsonb, 1, 'An ethics committee helps resolve conflicts about goals of care.', 'NNP 414 · Ethico-Legal Issues in Nephrology'),
(3, 71, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'When the purpose of a study is to explain the underlying causes of phenomena, the study is:', '["Explanatory", "Predictive", "Developmental", "Descriptive"]'::jsonb, 0, 'Explanatory research seeks to understand the underlying causes of, or reasons for, phenomena.', 'NNP 418 · Research Methods and Statistics'),
(3, 72, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Which insertion site for a central venous catheter is generally associated with the LOWEST risk of catheter-related bloodstream infection?', '["Internal jugular vein with a dressing changed daily", "Subclavian vein", "Femoral vein", "Any site is equally low-risk once inserted"]'::jsonb, 1, 'The subclavian site is associated with a lower infection risk compared with the femoral or internal jugular sites, which is why it is often preferred for longer-term central access when feasible.', 'NNP 418 · Research Methods and Statistics'),
(3, 73, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A survey is always a ______ study.', '["Classroom", "Office", "Field", "Laboratory"]'::jsonb, 2, 'Surveys are done in the field, among people in their real settings, not in a laboratory.', 'NNP 418 · Research Methods and Statistics'),
(3, 74, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', '______ describes the present state of affairs as it exists without having any control over variables.', '["Descriptive research", "Applied research", "Analytical research", "Distinctive research"]'::jsonb, 0, 'Descriptive research describes existing conditions without manipulating variables.', 'NNP 418 · Research Methods and Statistics'),
(3, 75, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A study measuring both nurses'' workload and their reported levels of burnout to determine whether the two are related, without manipulating either variable, uses a', '["Case-control design with random assignment", "True experimental design", "Correlational design", "Historical design"]'::jsonb, 2, 'This design examines the naturally occurring association between two measured variables (workload and burnout) without manipulation, characteristic of a correlational design.', 'NNP 418 · Research Methods and Statistics'),
(3, 76, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Research as a process provides the following EXCEPT', '["Reading", "Writing long essays", "Fills gaps and improves services", "Thinking"]'::jsonb, 1, 'The correct answer is: Writing long essays.', 'NNP 418 · Research Methods and Statistics'),
(3, 77, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A nurse is documenting patient information and notices that the file size is very large. The file size is measured in kilobytes (KB), but the nurse needs to know how many bytes are in one kilobyte. The correct answer is:', '["1,024 bytes", "100 bytes", "10,000 bytes", "1,000 bytes"]'::jsonb, 0, 'In computer science, a kilobyte is typically defined as 1,024 bytes (2^{10}), not a round 1,000, due to the binary nature of computers. This is a common point of confusion with the metric system.', 'NNP 418 · Research Methods and Statistics'),
(3, 78, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'On a chest X-ray, the tip of an adult endotracheal tube should lie about:', '["At the level of the vocal cords", "In the right main bronchus", "Below the carina in the left bronchus", "3–5 cm above the carina"]'::jsonb, 3, 'A tube that is too deep usually enters the right main bronchus.', 'NNP 418 · Research Methods and Statistics'),
(3, 79, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Which is NOT a characteristic of experimental design?', '["Randomisation", "Manipulation", "Variation", "Control"]'::jsonb, 2, 'True experiments have manipulation, control and randomisation.', 'NNP 418 · Research Methods and Statistics'),
(3, 80, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A correlational design differs from a true experimental design by:', '["Studying variables in an atypical setting", "Studying associations between phenomena", "Using a multidirectional approach", "Studying cause-and-effect relationships"]'::jsonb, 1, 'Correlational designs look for associations between variables without manipulating them, so they cannot prove causation.', 'NNP 418 · Research Methods and Statistics'),
(3, 81, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A test that shows positive when the true status is negative gives a:', '["True positive", "True negative", "False positive", "False negative"]'::jsonb, 2, 'A false positive is a positive test result when the true status is negative.', 'NNP 418 · Research Methods and Statistics'),
(3, 82, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'How many distinct steps are there in the nursing process?', '["4", "6", "7", "5"]'::jsonb, 3, 'The nursing process has 5 steps: assessment, diagnosis, planning, implementation and evaluation (ADPIE).', 'NNP 418 · Research Methods and Statistics'),
(3, 83, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Betty Neuman''s systems model focuses on:', '["Interpersonal phases of the relationship", "Self-care deficits and nursing systems", "Environmental cleanliness and fresh air only", "Responses to stressors and lines of defence"]'::jsonb, 3, 'Prevention is primary, secondary or tertiary.', 'NNP 418 · Research Methods and Statistics'),
(3, 84, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'The stimulus–response (classical conditioning) theory was propounded by:', '["Pavlov", "Bruner", "Piaget", "Maslow"]'::jsonb, 0, 'Ivan Pavlov''s classical conditioning is the basis of stimulus–response learning theory.', 'NNP 418 · Research Methods and Statistics'),
(3, 85, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'In order to achieve objective, organisations should apply the method of science to solve problems, with specific reference to operational research and advanced mathematical technique. This statement implies:', '["System theory", "Behavioural theory", "Management by objective", "Classical theory"]'::jsonb, 0, 'Applying scientific/mathematical methods to solve organisational problems reflects systems theory.', 'NNP 418 · Research Methods and Statistics'),
(3, 86, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Which of these is NOT a qualitative variable?', '["Religion", "Sex", "Marital status", "Age"]'::jsonb, 3, 'Age is a quantitative variable. Sex and marital status are qualitative (categorical).', 'NNP 418 · Research Methods and Statistics'),
(3, 87, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Which of the following databases is commonly used by nurses to search for research evidence?', '["WHO Policy Database", "PubMed/MEDLINE", "Statistical Package for Social Sciences (SPSS)", "Google Maps"]'::jsonb, 1, 'PubMed/MEDLINE is a major biomedical literature database frequently used by healthcare professionals to search for research evidence.', 'NNP 418 · Research Methods and Statistics'),
(3, 88, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A population that consists of an endless succession of values is:', '["A sample", "Finite", "Infinite", "Definitive"]'::jsonb, 2, 'A population with an endless (uncountable) succession of values is infinite.', 'NNP 418 · Research Methods and Statistics'),
(3, 89, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'The first page of a research report is the:', '["Index", "Title page", "Bibliography", "Appendix"]'::jsonb, 1, 'The title page is the first page of a research report.', 'NNP 418 · Research Methods and Statistics'),
(3, 90, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A perfect positive correlation is:', '["2.00", "0.10", "1.00", "0.00"]'::jsonb, 2, 'Correlation coefficients range from −1 to +1. A perfect positive correlation is +1.00.', 'NNP 418 · Research Methods and Statistics'),
(3, 91, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'The reliability index obtained from a test–retest procedure is the:', '["Coefficient of internal consistency", "Coefficient of stability", "Coefficient of equivalence", "Coefficient of rater stability"]'::jsonb, 1, 'Test–retest reliability gives the coefficient of stability. Parallel forms give equivalence; Cronbach''s alpha gives internal consistency.', 'NNP 418 · Research Methods and Statistics'),
(3, 92, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A researcher measures blood pressure using a sphygmomanometer in a study. This is an example of:', '["Qualitative data collection", "Physiological measurement", "Projective technique", "Observational technique"]'::jsonb, 1, 'Physiological measurement involves collecting biological or physical data using instruments such as sphygmomanometers, thermometers, or pulse oximeters.', 'NNP 418 · Research Methods and Statistics'),
(3, 93, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Which step of the research process involves condensing raw data into tables, charts, and summary statistics to make it more understandable?', '["Organisation and analysis of data", "Literature review", "Formulation of research questions", "Problem identification"]'::jsonb, 0, 'Organizing and analyzing data involves reducing and summarizing raw data into a manageable, interpretable form such as tables and charts.', 'NNP 418 · Research Methods and Statistics'),
(3, 94, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'When nurses help clients explore lifestyle habits and health behaviours to identify health risks, they are using which model?', '["Medical model", "Physiological model", "Psychosocial model", "Wellness model"]'::jsonb, 3, 'Wellness models look at lifestyle and health behaviours to identify risks and promote health.', 'NNP 418 · Research Methods and Statistics'),
(3, 95, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'According to Maslow''s hierarchy, the most basic needs are:', '["Self-actualisation needs", "Physiological needs", "Social needs", "Safety and security needs"]'::jsonb, 1, 'Physiological needs are the most basic in Maslow''s hierarchy.', 'NNP 418 · Research Methods and Statistics'),
(3, 96, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A researcher writes: ''What are the lived experiences of family members of patients admitted to the ICU?'' This is best classified as a', '["Qualitative research question", "Directional hypothesis", "Null hypothesis", "Statistical hypothesis requiring inferential testing"]'::jsonb, 0, 'This open-ended question exploring lived experience is characteristic of qualitative research questions rather than a hypothesis, which requires measurable variables and predicted relationships.', 'NNP 418 · Research Methods and Statistics'),
(3, 97, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Which of the following is one of the skills specifically used during the evaluation phase?', '["Performing surgery", "Interviewing", "Billing insurance", "Prescribing medication"]'::jsonb, 1, 'Talking with the patient (interviewing) is one of the direct ways a nurse gathers information to judge how care is progressing.', 'NNP 418 · Research Methods and Statistics'),
(3, 98, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A study that follows a group of people over time to observe the development of a condition is called a:', '["Case-control study", "Descriptive study", "Cross-sectional study", "Cohort study"]'::jsonb, 3, 'A cohort study follows participants over time, tracking exposure and outcomes to identify associations or risk factors.', 'NNP 418 · Research Methods and Statistics'),
(3, 99, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'Which is a characteristic of quantitative research?', '["A large sample is emphasised", "There are multiple subjective realities", "No generalisation is made from the findings", "Data are reported in a literary style"]'::jsonb, 0, 'Quantitative research stresses large, representative samples and generalisation. Multiple subjective realities and literary reporting are qualitative features.', 'NNP 418 · Research Methods and Statistics'),
(3, 100, 'Nephrology Nursing Mock — Day 5 Night (Nov 2026)', 'NNP 418 · Research Methods and Statistics', 'A test''s sensitivity is the proportion of:', '["Patients without the disease who test negative", "Patients with the disease who test positive", "Positive tests that are true positives", "All tests that are correct"]'::jsonb, 1, 'High sensitivity rules out disease when the test is negative (SnOut).', 'NNP 418 · Research Methods and Statistics');
